      "content": "{\n  \"name\": \"morning-star\",\n  \"version\": \"4.2.0\",\n  \"description\": \"Morning Star \\u2014 harness engineering workflow platform: TS Harness Workflow Engine + judgment skills, shipped as an Agent Plugin\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"workspaces\": [\n    \"packages/*\"\n  ],\n  \"scripts\": {\n    \"opencode:bundle-assets\": \"bun run --cwd packages/opencode bundle-assets\",\n    \"opencode-v2:bundle-assets\": \"bun run --cwd packages/opencode-v2 bundle-assets\",\n    \"opencode-v2:build\": \"bun run --cwd packages/opencode-v2 build\",\n    \"dsh:bundle-assets\": \"bun run --cwd packages/dsh bundle-assets\",\n    \"omp:bundle-assets\": \"bun run --cwd packages/omp bundle-assets\",\n    \"typecheck\": \"bun run typecheck:prepare && bunx tsc --pretty false && bun run --cwd packages/cli typecheck:src && bun run --cwd packages/dsh typecheck:src\",\n    \"typecheck:prepare\": \"bun run engine:build && bun run judgment:build && bun run --cwd packages/commands build && bun run ui:build\",\n    \"engine:build\": \"bun run --cwd packages/engine build\",\n    \"commands:build\": \"bun run --cwd packages/commands build\",\n    \"judgment:build\": \"bun run --cwd packages/judgment build\",\n    \"cli:dev\": \"MSTAR_CLI_PROJECT_ROOT=$PWD bun run --cwd packages/cli dev\",\n    \"cli:build\": \"bun run --cwd packages/cli build\",\n    \"cli:pack\": \"npm pack --workspace @mstar-harness/cli\",\n    \"opencode:build\": \"bun run --cwd packages/opencode build\",\n    \"opencode:pack\": \"npm pack --workspace @mstar-harness/opencode\",\n    \"opencode-v2:pack\": \"npm pack --workspace @mstar-harness/opencode-v2\",\n    \"dsh:build\": \"bun run --cwd packages/dsh build\",\n    \"omp:build\": \"bun run --cwd packages/omp build\",\n    \"omp:pack\": \"npm pack --workspace @mstar-harness/omp\",\n    \"hooks:build\": \"bun run scripts/build-zcode-hooks.ts\",\n    \"release:prepare\": \"bun run scripts/prepare-release.ts\",\n    \"release:validate\": \"bun run scripts/validate-release-version.ts\",\n    \"ci:dep-guard\": \"bun scripts/ci-dep-guard.ts\",\n    \"ci:packed-manifest-guard\": \"bun scripts/ci-packed-manifest-guard.ts\",\n    \"validation:standalone\": \"bun run scripts/standalone-smoke.ts\",\n    \"validation:drift\": \"bun run scripts/drift-lint.ts\",\n    \"lint:dsh-contract\": \"bun scripts/dsh-contract-lint.ts\",\n    \"lint:ascii-literals\": \"bun scripts/lint-ascii-literals.ts\",\n    \"lint:hash-gates\": \"bun scripts/lint-hash-gates.ts\",\n    \"lint:refusal-quality\": \"bun scripts/lint-refusal-quality.ts\",\n    \"lint:help-reachability\": \"bun scripts/lint-help-reachability.ts\",\n    \"ui:build\": \"bun run --cwd packages/ui build\"\n  },\n  \"packageManager\": \"bun@1.4.0\",\n  \"dependencies\": {\n    \"@mstar-harness/engine\": \"^4.2.0\"\n  },\n  \"devDependencies\": {\n    \"@oh-my-pi/pi-coding-agent\": \"^18.13.3\",\n    \"@types/hast\": \"^3.0.0\",\n    \"@types/mdast\": \"^4.0.0\",\n    \"@types/node\": \"^26.6.6\",\n    \"github-slugger\": \"^2.0.0\",\n    \"hast-util-from-html\": \"^2.0.3\",\n    \"mdast-util-from-markdown\": \"^2.0.3\",\n    \"mdast-util-gfm\": \"^3.1.0\",\n    \"mdast-util-to-string\": \"^4.0.0\",\n    \"micromark-extension-gfm\": \"^3.0.0\",\n    \"typescript\": \"^7.0.2\",\n    \"typescript5\": \"npm:typescript@^5.9.3\",\n    \"yaml\": \"^2.8.1\"\n  },\n  \"omp\": {\n    \"name\": \"morning-star-harness\",\n    \"description\": \"Morning Star multi-agent harness skills and iteration commands for omp.\"\n  }\n}\n"
