      "path": "packages/dsh/src/gates/workflow-policy.ts",
      "content": "/**\n * Workflow/ralph gate policy — the P-a name allowlist + P-b lease\n * attribution + P-c first-seen ask . The policy is the SINGLE\n * decision point for the four-tier `workflowGate` mode semantics\n * (`off | warn | ask | hard`, default `warn`): it turns one composed\n * {@link WorkflowGateInput}  into `allow | warn | ask | deny` + a\n * reason. The dispatch-gate listener maps the verdict to the\n * `tools/pre-execute` refusal vocabulary (`PreToolDecision`) — this module\n * NEVER throws and NEVER builds an approval path: an `ask` verdict flows\n * through dsh's own approval waterfall (fail-closed upstream, this gate\n * invents no answerer).\n *\n * Policy matrix (mode × P-a/P-b/P-c):\n *\n * | input | mode | verdict |\n * |---|---|---|\n * | uncovered InProgress plan (P-b) | `off` | allow — the gate short-circuits `off` before the policy; kept here for a total policy |\n * | uncovered InProgress plan (P-b) | `hard` | deny — reason cites the uncovered plan id, veto before any child starts |\n * | uncovered InProgress plan (P-b) | `warn`/`ask` | warn — allowed + advisory verdict + one warn (the ask channel is for first-seen NAMES, never the workspace red line) |\n * | ralph (no `meta.name`), covered/read-only | any | allow — P-a/P-c NEVER apply to ralph (no allowlist identity); P-b applies |\n * | workflow, name ∈ `workflowNames` (non-empty list), covered | any | allow — the allowlist passes under every mode |\n * | workflow, unknown (empty/absent list ⇒ EVERY name unknown), covered | `off` | allow — the gate short-circuits `off` before the policy; kept here for a total policy |\n * | workflow, unknown, covered | `warn` | warn — advisory + one warn (centralized) |\n * | workflow, unknown, covered | `hard` | deny — reason names the workflow name, veto before any child starts |\n * | workflow, unknown, covered, first-seen (no cached decision) | `ask` | ask — `{kind:'ask'}` through the approval waterfall + the name is marked asked (W-1 — the run-start observation promotes only asked names to allow) |\n * | workflow, unknown, covered, cached allow | `ask` | allow — cached decision, NO re-ask |\n * | workflow, unknown, covered, cached deny | `ask` | deny — cached decision, NO re-ask |\n *\n * P-c cache lifecycle: the {@link WorkflowAskCache} is apply-scoped — created\n * per plugin `apply` (owned by the host adapter, constructed with it) and\n * closed over by the listener; there is NO module-level Map, so disposal\n * (fiber teardown / HMR reload) makes the cache unreachable with the apply\n * and a fresh apply starts with an empty cache. The cache records only\n * RESOLVED decisions (`allow` | `deny`) keyed by workflow name.\n *\n * Cache-key normalization (the congruence fix): every key — the gate's `metaName` (composed through\n * {@link normalizeWorkflowName} in dispatch.ts `workflowGateInputOf`), the\n * run-start observation's `runName` (workflow-ledger.ts), and the explicit\n * `record()` / `markAsked()` APIs (which normalize internally) — is\n * the ASCII-control-char-stripped, UNCAPPED name. One shared function, both\n * seams; a control-char name (`au\\u0000dit`) gates and observes under the\n * same normalized key (`audit`), and the length is never capped on the\n * identity axis (the ledger ROW display field is capped separately — the\n * cache key stays the full name, matching the gate).\n *\n * Answer-recording seam (`WorkflowAskCache.record` + W-1 `markAsked`): the\n * gate CANNOT observe the ask outcome directly — the tool registry's\n * `serviceAsk` consumes the approval result internally (`deepseek-harness\n * packages/core/tools/src/index.ts`, `prepareExecution`/`serviceAsk`) — so\n * the ANSWER reaches the cache through the workflow-ledger consumer's\n * run-start observation : an ALLOWED ask executes the call, the\n * durable `tool-workflow/run-start` session event carries the run name, and\n * the consumer records `allow` for it (`workflow-ledger.ts`). The policy\n * marks every name that received an `ask` verdict in this apply\n * (`markAsked`, at the single ask point), and the observation promotes ONLY\n * marked names to `allow` — a run observed WITHOUT a prior ask (a P-b\n * advisory under `ask` mode, a `warn`/`off`-mode run) is NOT an approval\n * resolution and never pre-authorizes the name . A DENIED answer\n * produces no run → no observation → the next same-name call re-asks\n * (fail-closed — no grant evidence, never an invented allow). The explicit\n * `record()` API stays the general seam — an answerer integration or the\n * tests may drive it directly, and an unresolved first-seen re-asks per\n * call until the observation (or an explicit record) lands.\n *\n * Module boundary: no barrel. This module imports dispatch.ts TYPE-ONLY\n * (`WorkflowGateInput` — erased at runtime, no cycle); dispatch.ts imports\n * the policy/cache values from here. The P-a vocabulary\n * (`workflowNameUnknown`, `WORKFLOW_NAME_UNKNOWN_CODE`) centralized HERE from\n * 's dispatch.ts.\n */\nimport type { Config } from './_shared.ts'\nimport type { WorkflowGateInput } from './dispatch.ts'\n\n/**\n * The workflow-gate advisory/deny violation code for a name outside the P-a\n * allowlist (warn-mode advisory / hard-mode veto reason — Task 2/3 policies\n * share this vocabulary).\n */\nexport const WORKFLOW_NAME_UNKNOWN_CODE = 'workflow.name.unknown'\n\n/**\n * The workflow-gate advisory/deny violation code for P-b lease attribution\n * : the calling workspace has an `InProgress` plan without\n * `execution_lease` coverage (warn-mode advisory / hard-mode veto reason —\n * the reason cites the uncovered plan id).\n */\nexport const WORKFLOW_LEASE_UNCOVERED_CODE = 'workflow.lease.uncovered'\n\n/** ASCII control characters (C0 + DEL) — stripped from workflow names (the log-forging surface(. */\nconst WORKFLOW_NAME_CONTROL_CHARS = /[\\u0000-\\u001F\\u007F]/g\n\n/**\n * Strip ASCII control characters (newlines / tabs / CR — the log-forging\n * surface( from one workflow name. THE shared P-c cache-key\n * normalization : the gate's `metaName` (composed in\n * dispatch.ts `workflowGateInputOf`) and the run-start observation's\n * `runName` (workflow-ledger.ts) MUST key the ask cache through the SAME\n * function — a raw-vs-stripped mismatch (e.g. `au\\u0000dit` gating under\n * one key while the observation records another) would re-ask a resolved\n * name forever. Pure — NEVER throws. The ledger's other display fields\n * (`label` / `phase`) use the same strip; ID-sized fields (`runId` /\n * `childId`) are NOT routed here — they keep their skip-if-oversized\n * semantics.\n */\nexport function normalizeWorkflowName(value: string): string {\n  return value.replace(WORKFLOW_NAME_CONTROL_CHARS, '')\n}\n\n/**\n * P-a allowlist membership: a workflow name is UNKNOWN when `workflowNames`\n * is absent or empty (⇒ every name unknown — documented, the gate is NOT\n * \"allow all\" by omission) or the name is not listed. Ralph calls carry no\n * `meta.name` — P-a never applies to them (callers guard on\n * `input.metaName !== undefined` first).\n *\n * Comparison boundary: entries are normalized through\n * {@link normalizeWorkflowName} BEFORE the comparison — the gate's\n * `metaName` is already stripped, so an operator-pasted control-char\n * variant (trailing newline, copied config value) matches the same\n * identity instead of silently degrading to unknown. The operator's config\n * array is NEVER mutated — the normalization happens at the boundary only.\n */\nexport function workflowNameUnknown(config: Config, metaName: string): boolean {\n  const names = config.workflowNames\n  if (names === undefined || names.length === 0) return true\n  return !names.some((entry) => normalizeWorkflowName(entry) === metaName)\n}\n\n/** One workflow name's resolved P-c decision (the cache value). */\nexport type WorkflowAskCacheDecision = 'allow' | 'deny'\n\n/**\n * The P-c per-session first-seen cache: workflow name → resolved decision.\n * Apply-scoped (one instance per plugin `apply`, owned by the host adapter —\n * see the module doc for the lifecycle). Records ONLY resolved decisions; a\n * miss means first-seen (or an unanswered ask) → the policy asks again.\n *\n * The cache ALSO tracks which names received an `ask`\n * verdict in this apply ({@link markAsked} — the gate marks EVERY ask\n * decision at the policy's single ask point). The run-start observation\n * (workflow-ledger.ts) records `allow` ONLY for names marked-asked — a run\n * that happened without an ask (P-b advisory under `ask` mode, a\n * `warn`/`off`-mode run) is NOT an approval resolution and must not\n * pre-authorize the name.\n *\n * The WRITE seams ({@link record} / {@link markAsked})\n * normalize their keys internally — the \"ONE shared normalization\" contract\n * holds even for a caller that passes a raw spelling (today's production\n * callers already normalize before calling; this is defense-in-depth for the\n * documented answerer-integration seam). {@link get} stays a verbatim read —\n * the gate always passes the normalized `metaName`, and the raw spelling is\n * never stored (test 13 pins that).\n */\nexport class WorkflowAskCache {\n  private readonly decisions = new Map<string, WorkflowAskCacheDecision>()\n  /** Names that received an `ask` verdict in this apply (W-1 — the observation promotes ONLY asked names to allow). */\n  private readonly asked = new Set<string>()\n  // simplify: both collections are uncapped — growth is apply-scoped and only\n  // via ask verdicts / resolved decisions (an unresolved first-seen re-asks\n  // without inserting). Add a cap or TTL if long-lived sessions with high\n  // distinct-name ask volume ever show up in profiling.\n  /** The resolved decision for `name`, or undefined when never resolved. */\n  get(name: string): WorkflowAskCacheDecision | undefined {\n    return this.decisions.get(name)\n  }\n\n  /**\n   * Record the approval-flow outcome for `name` (the ask's ANSWER — the\n   * answerer integration's seam; see the module doc). Subsequent same-name\n   * calls under `ask` reuse the cached decision without re-asking. The key\n   * is normalized internally, so a raw spelling records under the key the gate\n   * reads.\n   */\n  record(name: string, decision: WorkflowAskCacheDecision): void {\n    this.decisions.set(normalizeWorkflowName(name), decision)\n  }\n\n  /**\n   * Mark `name` as having received an `ask` verdict in this apply (W-1).\n   * Called by the policy on EVERY ask decision, BEFORE the verdict is\n   * returned — the run-start observation promotes only marked names to\n   * `allow`. The key is normalized internally.\n   */\n  markAsked(name: string): void {\n    this.asked.add(normalizeWorkflowName(name))\n  }\n\n  /** Whether `name` received an `ask` verdict in this apply (the observation's promote gate). Normalizes internally. */\n  wasAsked(name: string): boolean {\n    return this.asked.has(normalizeWorkflowName(name))\n  }\n}\n\n/** The four-tier policy decision vocabulary (plan W-B3). */\nexport type WorkflowPolicyDecision = 'allow' | 'warn' | 'ask' | 'deny'\n\n/**\n * One policy verdict: the decision + a human-readable reason + the violation\n * code for the warn/ask/deny vocabulary (the caller emits `code` in the\n * advisory row — the gate never guesses which policy fired).\n */\nexport type WorkflowPolicyVerdict =\n  | { decision: 'allow'; reason?: undefined; code?: undefined }\n  | { decision: 'warn' | 'ask' | 'deny'; reason: string; code: string }\n\n/**\n * The workflow/ralph gate policy — P-a name allowlist + P-c first-seen ask\n * . `config` + cache + composed\n * input → verdict; the caller (dispatch gate) maps the verdict to the\n * `PreToolDecision` refusal vocabulary and owns the advisory emit/log\n * infrastructure. The ONE cache write is contained: an `ask` verdict marks\n * the name via `WorkflowAskCache.markAsked` (W-1 — see the cache doc)\n * before returning; `markAsked` never throws. NEVER throws.\n *\n * P-b: `input.uncoveredPlanId` (the dispatch gate computes it from the\n * ACTIVE workflow snapshot — `workflows/<id>/snapshot.json`, the v3\n * status.json consumer; see dispatch.ts `writableFanOutUncovered`)\n * → hard denies (reason cites the plan id), warn/ask emit the advisory\n * verdict; `off` always allows. Preempts P-a/P-c: an orphan InProgress plan\n * is a workspace red line independent of the workflow name.\n * P-a: `metaName ∈ workflowNames` (empty/absent list ⇒ every name unknown);\n * allowlisted → allow under ANY mode. Unknown → per-mode: `warn` → advisory\n * verdict; `hard` → deny (reason names the workflow name); `ask` → first-seen\n * `{kind:'ask'}` verdict, afterwards the cached decision (allow/deny), never\n * a re-ask for a resolved name. Ralph carries no `meta.name` — P-a/P-c never\n * apply to it (P-b applies).\n */\nexport function workflowPolicy(config: Config, cache: WorkflowAskCache, input: WorkflowGateInput): WorkflowPolicyVerdict {\n  const mode = config.workflowGate ?? 'warn'\n  // The gate short-circuits `off` before the policy — kept for a total\n  // policy (a caller that skips the short-circuit still cannot block).\n  if (mode === 'off') return { decision: 'allow' }\n  // P-b row-scope attribution — FIRST, a workspace-level red line that\n  // applies to workflow AND ralph (no `meta.name` needed): the calling\n  // workspace has an `InProgress` plan without a recorded row scope.\n  // It preempts the name-based policies — an orphan plan means NO writable\n  // fan-out should start children until the plan is recovered, regardless of\n  // allowlist identity (same red line as the Assignment-keyed lease gate).\n  if (input.uncoveredPlanId !== undefined) {\n    if (mode === 'hard') {\n      return {\n        decision: 'deny',\n        code: WORKFLOW_LEASE_UNCOVERED_CODE,\n        reason: `workflow gate (${input.tool}) vetoed: plan \"${input.uncoveredPlanId}\" is InProgress without a recorded row scope (workflowGate: hard — record it through \\`mstar plan prepare --worktree-path <abs> --working-branch <name>\\` before writable fan-out)`,\n      }\n    }\n    // warn / ask: allowed with an advisory verdict + one warn. The ask\n    // channel is for first-seen NAMES (P-c), never a substitute for the\n    // workspace red line — an uncovered workspace stays advisory-only unless\n    // the deployment opts into hard.\n    return {\n      decision: 'warn',\n      code: WORKFLOW_LEASE_UNCOVERED_CODE,\n      reason: `plan \"${input.uncoveredPlanId}\" is InProgress without a recorded row scope (workflowGate: warn — advisory only; record it through \\`mstar plan prepare\\`)`,\n    }\n  }\n  if (input.metaName === undefined) {\n    // Ralph has no allowlist identity — P-a/P-c never apply (documented);\n    // P-b ran above (no uncovered plan → allow).\n    return { decision: 'allow' }\n  }\n  const name = input.metaName\n  // P-a: allowlisted names pass under every mode.\n  if (!workflowNameUnknown(config, name)) return { decision: 'allow' }\n  switch (mode) {\n    case 'warn':\n      return {\n        decision: 'warn',\n        code: WORKFLOW_NAME_UNKNOWN_CODE,\n        reason: `workflow name \"${name}\" is not in the workflowNames allowlist (workflowGate: warn — advisory only)`,\n      }\n    case 'hard':\n      return {\n        decision: 'deny',\n        code: WORKFLOW_NAME_UNKNOWN_CODE,\n        reason: `workflow gate (${input.tool}) vetoed: workflow name \"${name}\" is not in the workflowNames allowlist (workflowGate: hard)`,\n      }\n    case 'ask': {\n      const cached = cache.get(name)\n      if (cached === 'allow') return { decision: 'allow' }\n      if (cached === 'deny') {\n        return {\n          decision: 'deny',\n          code: WORKFLOW_NAME_UNKNOWN_CODE,\n          reason: `workflow gate (${input.tool}) vetoed: workflow name \"${name}\" was denied earlier in this session (workflowGate: ask — cached decision)`,\n        }\n      }\n      // First-seen (or an unanswered ask — no resolution recorded yet):\n      // route through dsh's approval waterfall (fail-closed upstream).\n      // Mark the name asked BEFORE the ask verdict is\n      // returned — the run-start observation promotes ONLY asked names to\n      // `allow`, so a run that happens without an ask (P-b advisory under\n      // ask mode, warn/off-mode runs) never pre-authorizes the name. A\n      // denied/unanswered ask leaves the mark harmless: no run → no\n      // observation → the next call re-asks (fail-closed preserved).\n      cache.markAsked(name)\n      return {\n        decision: 'ask',\n        code: WORKFLOW_NAME_UNKNOWN_CODE,\n        reason: `workflow name \"${name}\" is not in the workflowNames allowlist (workflowGate: ask — first-seen; approve to allow this session, or deny to veto; the decision is cached)`,\n      }\n    }\n  }\n}\n"
    },
    {
      "path": "packages/dsh/src/gates/status.ts",
      "content": "/**\n * Status gate — `{HARNESS_DIR}` coordination-document fs-intent gating\n *. *\n * The gate runs on `fs/write-intent` / `fs/edit-intent` (registered by the\n * entry `apply` with `prepend`), sharing ONE validation code path with the\n * host adapter's `beforeStatusWrite` hook (`validateStatusValue` /\n * `validateStatusDoc` are the module's wiring exports for the adapter).\n * Enforcement is the status-gate repair-escape contract: the intent waterfall\n * carries no incoming content, so hard mode with an ALREADY-invalid document\n * allows the write as a repair (loud error log + `repair: true` advisory) —\n * EXCEPT the store-authority refusal class, which no write can repair and\n * which is therefore vetoed (throw; {@link StatusVetoError}).\n *\n * Module boundary: no barrel — the entry and the adapter import by explicit\n * relative path; public exports (`StatusGateAdvisory`) are re-exported\n * verbatim by the entry.\n */\nimport { existsSync } from 'node:fs'\nimport { basename, join, relative, resolve } from 'node:path'\nimport { type Context } from '@deepseek-ai/cordis'\nimport {\n  applyEnforcement,\n  findingsCleanupGate,\n  readJson,\n  resolveProjectDir,\n  resolveRepoEnforcement,\n  resolveWorkflowDir,\n  validateProjectRegister,\n  validateStatus,\n  validateWorkflowSnapshot,\n  PROJECT_REGISTER_FILE,\n  WORKFLOW_SNAPSHOT_FILE,\n} from '@mstar-harness/engine'\nimport type {\n  GateResult,\n  StatusV2Doc,\n  ValidationResult,\n} from '@mstar-harness/engine'\nimport type { FsTarget, FsVersion, FsWriteIntent } from '@deepseek-ai/dsh-fs'\nimport { STATUS_FILE, asRecord, formatViolation, HarnessResolver, actorAgentOf } from './_shared.ts'\nimport type { Config } from './_shared.ts'\nimport { storeAuthorityRefusals } from './store-authority.ts'\n// Type-only (erased at runtime — no cycle): the adapter owns the shared\n// status-gate core and is constructed by the entry `apply`; the listener\n// signatures type their adapter parameter through the adapter module.\nimport type { DshHostAdapter } from './adapter.ts'\n/** Logger label for the status gate (dsh logger naming: `<scope>/<subject>`). */\nconst LOGGER_NAME = 'mstar/status-gate'\n/**\n * Advisory emitted on status-gate decisions (the plan's \"emit `agent/status`\n * (advisory)\" step). Named `mstar/status-gate` instead: the dsh `agent/status`\n * event is a lifecycle-only channel (`{ agent, status }`, idle ⇄ running, with\n * an invariant rejecting no-op transitions) — emitting gate warnings on it\n * would violate the seam contract. Consumers (later tasks, catalogs) observe\n * this event for model-visible/session-log surfacing.\n *\n * The status gate throws only the typed store-authority veto\n * ({@link StatusVetoError}) — the one refusal this content-blind seam CAN\n * make, because no write to the document can repair an unreadable issue\n * authority. Every other decision surfaces through this advisory: the intent\n * waterfall carries no incoming content, so the only hard-mode decision about\n * an ALREADY-invalid document is to allow the write as a repair escape.\n * Unexpected internal errors degrade to an allow with `degraded: true`.\n */\nexport interface StatusGateAdvisory {\n  /** Which intent slot passed the gate. */\n  operation: 'write' | 'edit'\n  /** `displayPath` of the guarded file. */\n  target: string\n  /** The gate verdict (warn-mode: `hardBlocked` false; hard repair escape: `hardBlocked` true). */\n  result: GateResult\n  /**\n   * Resolved enforcement flag: true whenever the gate ran under hard\n   * enforcement — for hard-mode repair escapes AND for degraded-hard\n   * advisories (f9: the catch emits `hard` reflecting ACTUAL enforcement,\n   * so a hard deployment can distinguish a dead control from a warn-only\n   * pass). False only for warn-mode advisories.\n   */\n  hard: boolean\n  /** True when hard mode allowed a write/edit to an ALREADY-invalid document (repair escape). */\n  repair?: boolean\n  /** True when the gate errored internally and degraded to allow (error-containment envelope). */\n  degraded?: boolean\n}\n/**\n * Canonical `{HARNESS_DIR}` coordination-document kinds the status gate\n * covers (opencode-parity vocabulary — the SAME three kinds the P2-fixed\n * opencode `harnessDocKindOfTarget` classifies): the v2 root `status.json`,\n * `workflows/<id>/snapshot.json`, and `projects/<id>/residuals.json`. Each\n * kind maps to its matching engine validator in\n * {@link validateStatusValue}.\n */\nexport type HarnessDocKind = 'status' | 'snapshot' | 'register'\n\n/**\n * Classify one fs target as a canonical `{HARNESS_DIR}` coordination\n * document: basename ∈ {status.json, snapshot.json, residuals.json} AND the\n * harness-relative path matches the canonical home (root `status.json`,\n * `{WORKFLOW_DIR}/<id>/snapshot.json`, `{PROJECT_DIR}/<id>/residuals.json`\n * — one path component each, mirroring the P2-fixed opencode\n * `harnessDocKindOfTarget`).\n *\n * Phase-5 F1: the snapshot/register rel is computed against the RESOLVED\n * layout dirs (`resolveWorkflowDir` / `resolveProjectDir` — a `.mstarc`\n * `[config] workflow_dir` / `project_dir` declaration wins, defaults\n * `workflows` / `projects` under the harness dir), so a custom layout\n * classifies at the same location the runtime writes; resolver failure\n * (never expected with the explicit harness dir) falls back to the default\n * names.\n *\n * dsh divergence from the opencode probe (documented): opencode resolves\n * the harness root by marker probe (W-REV-1) with a declared-root fallback;\n * the dsh gates ALREADY resolve `{HARNESS_DIR}` per calling session\n * workspace through the shared `HarnessResolver` BEFORE the intent slot\n * runs, so classification here is against that resolved root — no second\n * probe, no W-REV-3 rebuild. Returns the kind when gated, `null` otherwise\n * (a non-coordination target, or a path outside the resolved harness dir —\n * the gate is inert for them).\n */\nexport function harnessDocKindOfTarget(harnessDir: string, targetPath: string): HarnessDocKind | null {\n  const resolved = resolve(targetPath)\n  const name = basename(resolved)\n  // The register name matches CASE-INSENSITIVELY (plan QC fix wave FW-3): on\n  // a case-insensitive volume (Darwin/APFS) a case-variant basename\n  // (`RESIDUALS.json`) IS the register file, and the document gate must see\n  // what the store-authority route sees (omp/ZCode parity). The status and\n  // snapshot names keep their exact match.\n  const isRegisterName = name.toLowerCase() === PROJECT_REGISTER_FILE\n  if (name !== STATUS_FILE && name !== WORKFLOW_SNAPSHOT_FILE && !isRegisterName) return null\n  const rel = relative(harnessDir, resolved)\n  if (name === STATUS_FILE && rel === STATUS_FILE) return 'status'\n  let workflowDir: string\n  let projectDir: string\n  try {\n    workflowDir = resolveWorkflowDir(harnessDir, { harnessDir })\n    projectDir = resolveProjectDir(harnessDir, { harnessDir })\n  } catch {\n    workflowDir = join(harnessDir, 'workflows')\n    projectDir = join(harnessDir, 'projects')\n  }\n  if (name === WORKFLOW_SNAPSHOT_FILE && /^[^/]+\\/snapshot\\.json$/.test(relative(workflowDir, resolved))) return 'snapshot'\n  if (isRegisterName && /^[^/]+\\/residuals\\.json$/i.test(relative(projectDir, resolved))) return 'register'\n  return null\n}\n\n/**\n * Resolve the hard-enforcement flag: explicit Config override wins, else\n * the repo `.mstarc` `[config] enforcement`, else the iteration compass\n * frontmatter (`resolveRepoEnforcement`), else warn-only.\n */\nfunction resolveHard(harnessDir: string, config: Config): boolean {\n  if (config.enforcement === 'hard') return true\n  if (config.enforcement === 'soft') return false\n  return resolveRepoEnforcement(harnessDir).hard\n}\n\n/**\n * The violation code the snapshot cleanup extension raises when the issue\n * authority cannot be consulted at all — missing (`store.not-initialized`),\n * staged (`store.not-active`), corrupt (`store.corrupt`), below-floor /\n * capability-less (`store.runtime-unsupported`), drifted (`store.schema-*`) or\n * busy store. The store-authority refusal class: the cleanup gate's VERDICT is\n * unknown, as opposed to a cleanup violation the authority actually reported.\n *\n * The fs-intent repair escape is unsound for this class: the violation says the\n * authority could not be READ, so the write that would \"repair\" it is a store\n * command (`mstar store init|upgrade|migrate`), never a write to the document —\n * every document write admissible under the escape is instead an evasion of the\n * very plan row the closure gate is asking about (dropping its\n * `metadata.findings_cleanup` mode while no authority can re-derive the\n * violation).\n */\nconst CLEANUP_AUTHORITY_UNAVAILABLE_CODE = 'findings.cleanup-authority-unavailable'\n\n/**\n * Typed hard-mode veto for the status gate's store-authority refusal class\n * (the dsh fs-policy veto channel: \"veto = throw\"; the fs tool turns the throw\n * into an isError tool result carrying `{ name, code }`). Two decision\n * classes throw it:\n *\n * - the UNCONDITIONAL store-authority refusals (G4b, plan QC fix wave FW-1):\n *   a hand write of `{HARNESS_DIR}/store.db` (`store.direct-write-refused`) or\n *   of a retired/unreadable-authority register (`project.register.retired` /\n *   `store.authority-unavailable`) — an authority invariant, vetoed in BOTH\n *   enforcement modes;\n * - the hard-mode cleanup-authority class (see\n *   {@link CLEANUP_AUTHORITY_UNAVAILABLE_CODE}) — the repair escape every\n *   other violation class still gets is unavailable there.\n *\n * The content-blind listener has no incoming content to lint, but it does not\n * need any for THESE decisions: they are about the authority itself, which no\n * content can change.\n */\nexport class StatusVetoError extends Error {\n  /** Stable code for tool-result serialization (the `{ name, code }` convention). */\n  readonly code = 'status.veto' as const\n  /** The violations that caused the veto (the store-authority refusal included). */\n  readonly violations: readonly ValidationResult[]\n\n  constructor(target: string, violations: readonly ValidationResult[], header: string) {\n    super(\n      `${target} write vetoed — ${header}:\\n${violations.map(formatViolation).join('\\n')}`,\n    )\n    this.name = 'StatusVetoError'\n    this.violations = violations\n  }\n}\n\n/**\n * Validate a PARSED harness coordination document through the\n * kind-matched engine validator (v2 root / workflow snapshot / project\n * register — the P2-fixed \"one validator per kind\" shape) plus the\n * snapshot-only `findingsCleanupGate` extension per plan row that\n * CONFIGURES a mode (the v1 per-plan-row cleanup gate relocated: plan rows\n * live on the snapshot, the plan's linked OPEN issues live in the issue\n * store). Shared by {@link validateStatusDoc} (the on-disk single-read path)\n * and the host adapter's `beforeStatusWrite` (the incoming document) — the\n * fs-intent gate, the adapter hook and the repair escape all surface the\n * SAME violation codes.\n *\n * ASYNC because the cleanup extension reads the issue authority\n * (`{HARNESS_DIR}/store.db`), the engine's async domain boundary. The\n * register kind stays SYNCHRONOUS shape validation: a project register is\n * migration history, and validating a document about to be written to that\n * retired path is not a lookup.\n * @param kind - the target's {@link HarnessDocKind} (matching engine validator).\n * @param harnessDir - the resolved `{HARNESS_DIR}`; required for the\n * snapshot kind's cleanup extension (it is the store context), otherwise\n * unused.\n */\nexport async function validateStatusValue(doc: unknown, kind: HarnessDocKind, harnessDir?: string | null): Promise<GateResult> {\n  if (kind === 'register') return validateProjectRegister(doc)\n  if (kind !== 'snapshot') return validateStatus(doc as StatusV2Doc)\n  const base = validateWorkflowSnapshot(doc)\n  if (!base.ok) return base\n  if (harnessDir === null || harnessDir === undefined) return base\n  const violations = await snapshotFindingsCleanupViolations(doc, harnessDir)\n  if (violations.length === 0) return base\n  return { ok: false, violations }\n}\n\n/**\n * The snapshot-target cleanup extension: for every snapshot plan row whose\n * `metadata.findings_cleanup` CONFIGURES a mode (zero-residual /\n * allow-residual — the P2 mode-resolution contract: explicit mode wins,\n * the v1 `plans[].metadata.findings_cleanup` mirror is deleted, no\n * dual-track), run the engine `findingsCleanupGate(context, planId, …)`\n * against the issue store: the plan's OPEN issues linked through\n * `provenance(kind='plan', target=<plan-id>)`, the single findings authority\n * (issue contract §4). A plan with no linked open issue passes.\n *\n * FAIL-CLOSED: the authority must be readable AND active. A missing\n * (`store.not-initialized`), staged (`store.not-active`), corrupt\n * (`store.corrupt`), below-floor or capability-less\n * (`store.runtime-unsupported`), drifted (`store.schema-*`) or busy store is\n * reported as a HIGH violation carrying the engine's own refusal message —\n * NEVER as \"no findings\". The store is never replaced by a JSON fallback:\n * the retired registers are migration history, not a second authority.\n */\nasync function snapshotFindingsCleanupViolations(doc: unknown, harnessDir: string): Promise<ValidationResult[]> {\n  const record = asRecord(doc)\n  if (record === undefined) return []\n  const violations: ValidationResult[] = []\n  for (const row of Array.isArray(record.plans) ? record.plans : []) {\n    const planRow = asRecord(row)\n    const metadata = planRow === undefined ? undefined : asRecord(planRow.metadata)\n    const mode = metadata?.['findings_cleanup']\n    if (mode !== 'zero-residual' && mode !== 'allow-residual') continue\n    const planId = typeof planRow?.id === 'string' ? planRow.id : typeof planRow?.plan_id === 'string' ? planRow.plan_id : undefined\n    if (planId === undefined) continue\n    try {\n      const gate = await findingsCleanupGate({ harnessDir }, planId, { mode })\n      violations.push(...gate.violations)\n    } catch (error) {\n      const code = (error as { code?: unknown } | null | undefined)?.code\n      violations.push({\n        ok: false,\n        severity: 'high',\n        code: CLEANUP_AUTHORITY_UNAVAILABLE_CODE,\n        message:\n          `the findings cleanup gate for plan ${planId} cannot be evaluated: ` +\n          `${typeof code === 'string' && code !== '' ? `[${code}] ` : ''}${(error as Error).message}`,\n        fix: 'restore the issue store (mstar store init|upgrade|migrate) — an unreadable findings authority is never treated as no findings',\n      })\n    }\n  }\n  return violations\n}\n\n/**\n * Run the status gate over the CURRENT on-disk document at a canonical\n * harness coordination target. The fs intent waterfall carries only\n * `(target, actor)` — never the incoming content — so the vetoable check\n * is the pre-write state (the opencode hook's fallback for the same\n * reason). The kind-matched validator runs via {@link validateStatusValue}\n * (the snapshot kind's `findingsCleanupGate` extension included) — schema\n * violations short-circuit it (the doc must parse for the cleanup gate to\n * be meaningful).\n *\n * Single-read contract: the file is parsed exactly once and the\n * parsed doc is passed to {@link validateStatusValue} — the previous\n * path-first read then `readJson` re-read was a TOCTOU window (a concurrent\n * writer between the two reads threw a raw error from inside the gate).\n * Malformed JSON is contained here with the engine's `status.invalid-json`\n * shape; never throws. Missing files are guarded by the callers\n * (`gateStatusIntent`, {@link DshHostAdapter.statusGate}) — first create has\n * no document to validate and passes before this function runs.\n * @param path - the canonical coordination-document path (root status.json\n * / workflow snapshot / project register — the caller classifies it).\n * @param kind - the target's {@link HarnessDocKind}.\n * @param harnessDir - the resolved `{HARNESS_DIR}` (the store context of the\n * snapshot kind's cleanup extension).\n */\nexport async function validateStatusDoc(path: string, kind: HarnessDocKind, harnessDir?: string | null): Promise<GateResult> {\n  let doc: unknown\n  try {\n    doc = readJson(path)\n  } catch (error) {\n    return {\n      ok: false,\n      violations: [{\n        ok: false,\n        severity: 'high',\n        code: 'status.invalid-json',\n        message: (error as Error).message,\n      }],\n    }\n  }\n  return await validateStatusValue(doc, kind, harnessDir)\n}\n\n/**\n * Gate one fs intent on a canonical `{HARNESS_DIR}` coordination document\n * (root `status.json` / `workflows/<id>/snapshot.json` /\n * `projects/<id>/residuals.json` — the v3 write-intent target set). The gate\n * throws only {@link StatusVetoError} (the store-authority refusal veto); it\n * never throws anything else. Warn mode logs + advisory emit + delegates; hard\n * mode with an ALREADY-invalid document logs an error-level REPAIR advisory\n * and delegates — the intent waterfall carries no incoming content, so a\n * hard veto here would deadlock the very write that repairs the document.\n * The coherent content-blind policy: invalid on-disk → allow-as-repair; valid\n * on-disk → normal validation path (pass). EXCEPTION (narrowed repair\n * escape): a store-authority refusal is vetoed instead — no write to the\n * document can repair an unreadable issue authority, so admitting the write\n * could only serve to remove the plan row the closure gate asks about while no\n * authority can re-derive the violation. Non-coordination targets and absent\n * documents are pure pass-through.\n *\n * Error-containment envelope: any unexpected error (TOCTOU race, backend\n * contract violation on `displayPath`, throwing advisory consumer) degrades\n * to allow in BOTH modes with a loud log + `degraded: true` advisory — an\n * untyped throw from the gate would spuriously block legitimate writes (the\n * fs waterfall has no error containment of its own).\n */\nasync function gateStatusIntent(\n  ctx: Context,\n  harnessDir: string | null,\n  config: Config,\n  adapter: DshHostAdapter,\n  operation: 'write' | 'edit',\n  target: FsTarget,\n): Promise<void> {\n  try {\n    if (harnessDir === null) return\n    const kind = harnessDocKindOfTarget(harnessDir, target.displayPath)\n    // FW-1/G4b: the store-authority refusal class is decided BEFORE any\n    // document validation and vetoes in BOTH enforcement modes — a hand write\n    // of the store database, or of a retired/unreadable-authority register,\n    // is an authority invariant no enforcement flag governs (the dsh\n    // `catalogRegistrationVeto` precedent). The pre-activation legacy register\n    // route returns no refusals and keeps the document path below.\n    const authorityRefusals = await storeAuthorityRefusals({\n      resolvedHarnessDir: harnessDir,\n      directKind: kind,\n      rawPath: target.displayPath,\n    })\n    if (authorityRefusals.length > 0) {\n      const hard = resolveHard(harnessDir, config)\n      ctx.logger(LOGGER_NAME).error(\n        `${target.displayPath} ${operation} VETOED (store-authority refusal class; unconditional — an authority invariant, not the enforcement flag):\\n${authorityRefusals.map(formatViolation).join('\\n')}`,\n      )\n      // The advisory is contained: a throwing consumer must not hand the\n      // catch below an error it would contain as a degrade-to-allow (the\n      // throw at the end of this branch IS the decision).\n      try {\n        ctx.emit('mstar/status-gate', { operation, target: target.displayPath, result: { ok: false, violations: authorityRefusals }, hard })\n      } catch (emitError) {\n        ctx.logger(LOGGER_NAME).error(`status gate veto advisory emit failed: ${(emitError as Error).message}`)\n      }\n      throw new StatusVetoError(\n        target.displayPath,\n        authorityRefusals,\n        'the issue/catalog authority is not hand-writable (store-authority refusal class; unconditional — an authority invariant, not the enforcement flag)',\n      )\n    }\n    if (kind === null) return\n    // The adapter owns the shared status-gate core (missing file = first\n    // create = pass); this listener adds enforcement + observability.\n    const result = await adapter.statusGate(target.displayPath, kind, harnessDir)\n    const hard = resolveHard(harnessDir, config)\n    const verdict = applyEnforcement(result, { hard })\n    if (!verdict.ok) {\n      if (verdict.hardBlocked) {\n        // The one refusal this seam CAN make: the store-authority class (see\n        // CLEANUP_AUTHORITY_UNAVAILABLE_CODE). Thrown past the error-containment\n        // envelope below, which contains UNEXPECTED errors only — the veto is a\n        // decision, and the fs-policy channel turns it into an isError write.\n        if (verdict.violations.some((violation) => violation.code === CLEANUP_AUTHORITY_UNAVAILABLE_CODE)) {\n          ctx.logger(LOGGER_NAME).error(\n            `status.json ${operation} VETOED (Enforcement: hard; the issue authority is unavailable, so the findings cleanup gate has no verdict — no filesystem write can repair that):\\n${verdict.violations.map(formatViolation).join('\\n')}`,\n          )\n          // The advisory is contained: a throwing consumer must not hand the\n          // catch below an error it would contain as a degrade-to-allow (the\n          // throw at the end of this branch IS the decision).\n          try {\n            ctx.emit('mstar/status-gate', { operation, target: target.displayPath, result: verdict, hard })\n          } catch (emitError) {\n            ctx.logger(LOGGER_NAME).error(`status gate veto advisory emit failed: ${(emitError as Error).message}`)\n          }\n          throw new StatusVetoError(\n            target.displayPath,\n            verdict.violations,\n            'Enforcement: hard — the issue authority cannot be consulted, so the findings cleanup gate has no verdict and no filesystem write can repair it',\n          )\n        }\n        // Repair escape: the current document is already invalid; this write\n        // may BE the repair, so allow it — but make the degraded control\n        // loud (error-level log + repair advisory, `hard: true`).\n        ctx.logger(LOGGER_NAME).error(\n          `status.json ${operation} ALLOWED as repair (Enforcement: hard; the current on-disk document is already invalid — the intent carries no incoming content, so the vetoable signal is only the pre-write state):\\n${verdict.violations.map(formatViolation).join('\\n')}`,\n        )\n        ctx.emit('mstar/status-gate', { operation, target: target.displayPath, result: verdict, hard, repair: true })\n      } else {\n        ctx.logger(LOGGER_NAME).warn(`status.json ${operation} (advisory):\\n${verdict.violations.map(formatViolation).join('\\n')}`)\n        ctx.emit('mstar/status-gate', { operation, target: target.displayPath, result: verdict, hard })\n      }\n    }\n  } catch (error) {\n    // The typed veto is rethrown untouched (the only throw this gate makes).\n    if (error instanceof StatusVetoError) throw error\n    ctx.logger(LOGGER_NAME).error(`status gate degraded to allow: ${(error as Error).message}`)\n    try {\n      // f9: the degraded advisory reflects ACTUAL enforcement mode — under\n      // hard the envelope still allows the write (never a veto), but the\n      // advisory carries `hard: true` so hard deployments can tell a dead\n      // control apart from a warn-only pass. `repair` stays unset (this was\n      // NOT a repair-escape allow — the gate errored, the write was never\n      // vetoed).\n      let hard = false\n      try {\n        hard = harnessDir !== null && resolveHard(harnessDir, config)\n      } catch {\n        // `resolveHard` reads `.mstarc`/compass frontmatter from disk — a\n        // throwing resolve must not re-enter the envelope (second-catch\n        // death loop); fall back to a fail-safe warn-mode advisory.\n      }\n      ctx.emit('mstar/status-gate', { operation, target: target.displayPath, result: { ok: true, violations: [] }, hard, degraded: true })\n    } catch (emitError) {\n      // Best-effort observability: a throwing advisory consumer must not take\n      // the gate down with it (the error log above is the durable signal).\n      ctx.logger(LOGGER_NAME).error(`status gate degraded advisory emit failed: ${(emitError as Error).message}`)\n    }\n  }\n}\n\n/**\n * `fs/write-intent` listener. Registered with `prepend` so this decider runs\n * BEFORE dsh-fs-policy regardless of mount order: the slot is first-wins by\n * registration order (dsh-fs-policy README), so without prepend a policy\n * plugin mounted earlier would make this gate unreachable. Every NON-VETO gate\n * decision (warn advisory, repair escape, degraded allow) calls `next()` —\n * delegating the observed-state intent decision to the remaining chain\n * (fs-policy when mounted; the bare `undefined` default otherwise) rather\n * than terminating the slot with `undefined` (which would silently disable\n * fs-policy's CAS for status.json in composed deployments). The store-authority\n * veto ({@link StatusVetoError}) is the single decision that does NOT delegate:\n * it rejects the waterfall so the write cannot land (dsh fs-policy \"veto =\n * throw\").\n */\nexport async function writeIntentListener(\n  ctx: Context,\n  resolver: HarnessResolver,\n  config: Config,\n  adapter: DshHostAdapter,\n  target: FsTarget,\n  actor: object | undefined,\n  next: () => FsWriteIntent | undefined | Promise<FsWriteIntent | undefined>,\n): Promise<FsWriteIntent | undefined> {\n  await gateStatusIntent(ctx, resolver.forAgent(actorAgentOf(actor)), config, adapter, 'write', target)\n  return await next()\n}\n\n/** `fs/edit-intent` listener — same gate and delegation contract as {@link writeIntentListener}. */\nexport async function editIntentListener(\n  ctx: Context,\n  resolver: HarnessResolver,\n  config: Config,\n  adapter: DshHostAdapter,\n  target: FsTarget,\n  actor: object | undefined,\n  next: () => { version: FsVersion } | undefined | Promise<{ version: FsVersion } | undefined>,\n): Promise<{ version: FsVersion } | undefined> {\n  await gateStatusIntent(ctx, resolver.forAgent(actorAgentOf(actor)), config, adapter, 'edit', target)\n  return await next()\n}\n"
    },
    {
      "path": "packages/dsh/src/gates/leaf-seat.ts",
      "content": "/**\n * The shared leaf-seat predicate of the dsh identity chain — the ONE shape\n * every dsh-side enforcement reads (ADR\n * `docs/adr/dsh-native-identity-channels.md`): a known leaf seat\n * (`header.origin === 'subagent'`, or a numeric `delegationDepth > 0`) can\n * never own an execution binding or hold a coordinator session.\n *\n * Consumers:\n * - `native-commands.ts` — the coordinator-seat-capable native tools\n *   (`mstar_plan_bind`, `mstar_execution_clear`) refuse a leaf seat\n *   fail-closed, before any admission or engine round-trip;\n * - the `tools/pre-execute` boundary below — the folded MCP surface's\n *   coordinator-seat commands refuse a leaf seat before the shared MCP client\n *   child ever executes. The refused set comes from this package's own\n *   `coordinator-seat.ts`, which follows the rule — not a new export — that\n *   `packages/commands/src/coordinator-seat.ts` owns for the CLI server's\n *   `--seat leaf` filter, so the two layers refuse the same actions (pinned by\n *   `tests/leaf-seat.spec.ts`). The shared `mstar-mcp` row is one generic\n *   connection for the whole host, so this host-side boundary is what covers a\n *   leaf naming a bound coordinator session there.\n */\nimport type { PreToolDecision, ToolExecution } from '@deepseek-ai/dsh-tools'\nimport type { ExecutionIdentity } from '@mstar-harness/engine'\nimport { coordinatorSeatCommandFor, coordinatorSeatToolNames } from './coordinator-seat.ts'\n\nexport function isLeafSeatHeader(header: unknown): boolean {\n  if (typeof header !== 'object' || header === null) return false\n  const view = header as { origin?: unknown; delegationDepth?: unknown }\n  return view.origin === 'subagent' || (typeof view.delegationDepth === 'number' && view.delegationDepth > 0)\n}\n\n/**\n * The §3.1 identity tuple the dsh transport hands the engine for one carrying\n * session: the leaf fact is ATTESTED here from the SAME shared predicate, so\n * the engine's `coordination.leaf-seat` receiver stays wired to a real\n * transport. Defense-in-depth only: the surfaces using it refuse a leaf\n * pre-admission first, so the engine refusal fires when another route skips\n * that check — never instead of it.\n */\nexport function coordinatorIdentityFor(\n  header: unknown,\n  sessionId: string,\n  workflowId: string,\n): ExecutionIdentity {\n  return {\n    source: 'host',\n    sessionId,\n    workflowId,\n    role: 'coordinator',\n    ...(isLeafSeatHeader(header) ? { leafSeat: true as const } : {}),\n  }\n}\n\n/**\n * The managed shell-env fact (#548): the ONE leaf predicate decides whether the\n * bash tool's per-execution environment exports `DSH_MSTAR_LEAF_SEAT=1`. The\n * CLI reads that marker and attests `leafSeat: true` on the §3.1 identity it\n * hands the engine, so a leaf-launched CLI process hits the engine's\n * `coordination.leaf-seat` refusal on coordinator registration verbs. The fact\n * is fail-closed only — it can restrict, never grant — and an env channel's\n * inherent limit stands: a leaf that strips the marker from its own environment\n * is not distinguishable.\n */\nexport const LEAF_SEAT_SHELL_ENV_KEY = 'DSH_MSTAR_LEAF_SEAT'\n\n/** The managed environment for one shell-tool execution: the marker for a leaf, nothing otherwise. */\nexport function leafSeatShellEnvOf(execution: { agent?: unknown }): Partial<Record<typeof LEAF_SEAT_SHELL_ENV_KEY, string>> {\n  return isLeafSeatHeader(sessionHeaderOf(execution.agent)) ? { [LEAF_SEAT_SHELL_ENV_KEY]: '1' } : {}\n}\n\n/** The model-visible description the shell-env contributor declares for the marker. */\nexport const LEAF_SEAT_SHELL_ENV_DESCRIPTION =\n  'Set to 1 when the calling session is a leaf/subagent seat; the mstar CLI attests it so the engine refuses workflow coordinator registration from this seat.'\n\n/**\n * Register the marker's shell-env contributor on the host registry. Deferred\n * injection (`ctx.inject`) keeps a composition without the shell-env plugin\n * loading — the registry is a host service this package never imports, so the\n * contributor shape is structural and the peer is optional.\n */\nexport function registerLeafSeatShellEnv(ctx: {\n  inject(names: string[], callback: (child: unknown) => void): unknown\n}): void {\n  ctx.inject(['shellEnv'], (child) => {\n    const registry = (child as {\n      shellEnv: {\n        register(contributor: {\n          name: string\n          variables: Record<string, { description: string }>\n          resolve(execution: { agent?: unknown }): Record<string, string>\n        }): unknown\n      }\n    }).shellEnv\n    registry.register({\n      name: 'mstar-leaf-seat',\n      variables: { [LEAF_SEAT_SHELL_ENV_KEY]: { description: LEAF_SEAT_SHELL_ENV_DESCRIPTION } },\n      resolve: (execution) => leafSeatShellEnvOf(execution),\n    })\n  })\n}\n\n/** The named cause every refusal carries (the seam's refusal vocabulary). */\nexport const LEAF_SEAT_COORDINATOR_CAUSE = 'leaf-seat.coordinator-action'\n\n/**\n * The cause for a seat-shaped call whose published tool name the MCP client\n * normalized or truncated into its collision form: the family cannot be\n * attributed, so the guard refuses instead of letting an unattributable name\n * through.\n */\nexport const LEAF_SEAT_UNATTRIBUTED_CAUSE = 'leaf-seat.unattributed-tool'\n\n/**\n * The collision suffix `@deepseek-ai/dsh-mcp-client` appends to a folded name it\n * could not publish verbatim (`publicToolName`, its lib/index.js): a character\n * outside `[A-Za-z0-9_-]` or a name over 64 characters makes the client rewrite\n * the joined name and return `<51-char prefix>_<12 hex of sha256(identity)>`.\n */\nconst COLLISION_SUFFIX = /_[0-9a-f]{12}$/\n\n/**\n * The known family tools one model-facing MCP tool name can select, or an empty\n * list when the name selects none.\n *\n * The published name is `mcp__<serverName>__<rawName>` and the server name is\n * deployment-owned: it may itself contain `__`, and the client's replacement or\n * truncation turns the name into the collision form above. Counting separators\n * therefore cannot recover the raw name — and a name this guard cannot\n * attribute must not pass silently, because the shared `mstar-mcp` row carries\n * no `--seat` to refuse it on the server side. So the name is matched against\n * the KNOWN folded family names instead: exactly when the raw name survived\n * (including a `__`-bearing server name and a normalized-but-untruncated\n * collision form), and by prefix when the client truncated the family name\n * (`mstar_pl` keeps only the head of `mstar_plan`).\n */\nfunction foldedSeatTools(toolName: string): readonly string[] {\n  if (!toolName.startsWith('mcp__')) return []\n  const plain = toolName.replace(COLLISION_SUFFIX, '')\n  const tools = coordinatorSeatToolNames()\n  const exact = tools.filter((tool) => plain.endsWith(`__${tool}`))\n  if (exact.length > 0) return exact\n  // No collision suffix: an unmatched name is another server's tool, not an\n  // mstar family.\n  if (plain === toolName) return []\n  const boundary = plain.lastIndexOf('__')\n  if (boundary < 'mcp__'.length) return []\n  const head = plain.slice(boundary + 2)\n  return head === '' ? [] : tools.filter((tool) => tool.startsWith(head))\n}\n\n/** The session header the leaf-seat contract reads (`agent.session.header`). */\nfunction sessionHeaderOf(agent: unknown): unknown {\n  return (agent as { session?: { header?: unknown } } | null | undefined)?.session?.header\n}\n\n/**\n * The named refusal for a known leaf calling a coordinator-seat command on the\n * folded MCP surface, else undefined. The tool `action` is visible here because\n * the MCP client registers every bridge tool as a normal `ToolDefinition`\n * (`ctx.tools.register`) and `tools/pre-execute` carries the parsed call in\n * `ToolExecution.arguments` — the same field the dispatch gate reads, so the\n * guard runs before the MCP child ever sees the call. The set of refused\n * commands is NOT listed here: `coordinatorSeatCommandFor` derives it from the\n * command definitions, following the same rule the CLI server's leaf seat\n * applies.\n * The recovery names the supported route (run it from the coordinating session)\n * and the actions this seat may run.\n */\nexport function leafSeatCoordinatorRefusal(exec: Pick<ToolExecution, 'name' | 'arguments' | 'agent'>): string | undefined {\n  const tools = foldedSeatTools(exec.name)\n  if (tools.length === 0) return undefined\n  const args = exec.arguments\n  if (typeof args !== 'object' || args === null || Array.isArray(args)) return undefined\n  const action = (args as { action?: unknown }).action\n  const commandId = tools.map((tool) => coordinatorSeatCommandFor(tool, action)).find((id) => id !== undefined)\n  if (commandId === undefined) return undefined\n  if (!isLeafSeatHeader(sessionHeaderOf(exec.agent))) return undefined\n  const leafCause =\n    'this seat is a leaf (session header origin \"subagent\" or a delegationDepth > 0), and coordinator seats belong to the ' +\n    'non-leaf coordinating session: run the operation from that session, or use the actions this seat may run ' +\n    '(plan.prepare / plan.progress / plan.show / plan.issue-add / plan.issue-close / issue.* / sdd.* / schema).'\n  if (tools.length === 1) {\n    return (\n      `${LEAF_SEAT_COORDINATOR_CAUSE}: ${exec.name} action \"${String(action)}\" (${commandId}) establishes or exercises a workflow coordinator seat, ` +\n      `and ${leafCause}`\n    )\n  }\n  // A truncated name keeps only the head of the family name, so more than one\n  // family could be the one this call selected: refuse rather than guess.\n  return (\n    `${LEAF_SEAT_UNATTRIBUTED_CAUSE}: ${exec.name} action \"${String(action)}\" is a workflow coordinator action of ${tools.join(' / ')}, ` +\n    'and the published tool name was rewritten or truncated by the MCP client (a server name with a replaced character or over 64 ' +\n    `characters), so the family it selects cannot be attributed; ${leafCause} ` +\n    'A connection whose server name needs neither replacement nor truncation (e.g. `serverName: mstar`) keeps every folded name attributable.'\n  )\n}\n\n/**\n * The `tools/pre-execute` listener: deny WITHOUT calling `next()` (the\n * waterfall short-circuit every refusal on this seam uses), delegate otherwise.\n */\nexport function leafSeatToolListener(exec: ToolExecution, next: () => Promise<PreToolDecision>): Promise<PreToolDecision> {\n  const refusal = leafSeatCoordinatorRefusal(exec)\n  return refusal === undefined ? next() : Promise.resolve({ kind: 'deny', reason: refusal })\n}\n"
    },
    {
      "path": "packages/dsh/src/gates/native-commands.ts",
      "content": "/**\n * The dsh-native tool surface — the mstar commands that cannot be MCP actions.\n *\n * A command is registered here ONLY when it satisfies one of two rules:\n *\n * 1. it is the PRODUCER of a dsh-local durable record the MCP route cannot\n *    write — `mstar_plan_bind` writes the `executionBinding` slot and the\n *    in-process adoption receipt that the ledger's attribution resolver and\n *    `mstar_execution_clear` read. The MCP `mstar_plan` action `bind` binds the\n *    engine row only; it cannot reach the dsh plugin's own store slot;\n * 2. it is a capability the MCP surface does not publish at all —\n *    `mstar_audit_validate` (the review-report credential scan behind\n *    `mstar audit scaffold`; the `mstar_audit` family publishes `scaffold` /\n *    `secret-scan` / `supply-chain`, none of which validates a report) and\n *    `mstar_execution_clear` (there is no shared `execution.clear` command).\n *\n * Everything else is the MCP surface (`mcp__mstar__<family>` with an `action`),\n * carried over the ONE shared `mstar-mcp` connection the bundle mounts for the\n * whole host. The fourteen 1:1 duplicates that used to shadow those MCP tools\n * here are gone: two identical model-facing surfaces cost ~10k characters of\n * fixed context per request and forced the model to choose between them.\n *\n * Identity: this native surface is the ONLY identity path — the shared MCP\n * connection carries none, and no MCP tool can supply one on a caller's behalf.\n * `mstar_plan_bind` calls the shared `@mstar-harness/commands`\n * implementation through its programmatic entry (`executeCommand` — the same\n * admission + execution path the CLI uses) and injects `sessionId` from\n * `exec.agent.id` (ADR `dsh-native-identity-channels` constraints 1–2:\n * `Agent.id` IS the session id). A session id in the tool arguments is\n * STRIPPED before admission — identity is never model-choosable on this\n * surface. `mstar_execution_clear` takes no parameters at all.\n *\n * No shell anywhere in the path: `executeCommand` runs in-process, and the\n * injected `effects` carry no process/browser/dashboard implementation, so an\n * effect-taking command can only refuse.\n *\n * Engine refusal envelopes surface verbatim: the bind tool validates nothing\n * beyond the platform's own parameter schema (mechanically mirrored from the\n * command's published JSON Schema, with the session selector removed) and\n * returns the `CommandEnvelope` it received as the canonical value — no\n * second validation layer, no paraphrase.\n *\n * Module boundary: self-contained for the bind adoption, the report validator\n * and the clear — the only imports are the cordis context type, the dsh-tools\n * seam, `@mstar-harness/commands`, the engine's execution-session primitives,\n * the seam validator (`seams.ts`) plus the shared violation view, the\n * execution-session clear internals, the shared leaf-seat predicate\n * (`leaf-seat.ts`), the adoption-root receipt (`execution-binding-roots.ts`),\n * and the shared cwd reader / workflow-selection resolvers.\n *\n * Leaf guard: the coordinator-seat-capable tools (`mstar_plan_bind`,\n * `mstar_execution_clear`) refuse a known leaf seat FAIL-CLOSED before any\n * admission or store read — the named guard the removed execution-session\n * command enforced. The same session-header predicate also ATTESTED the fact on\n * the §3.1 identity this file hands the engine (`leafSeat`), so the engine's\n * `validateExecutionIdentity` refuses `coordination.leaf-seat` behind it: the\n * engine holds no second leaf rule, only the adapter-attested fact.\n */\nimport { existsSync, readFileSync } from 'node:fs'\nimport { resolve } from 'node:path'\nimport { type Context } from '@deepseek-ai/cordis'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { ToolExecution } from '@deepseek-ai/dsh-tools'\nimport {\n  decodeExecutionSessionRef,\n  encodeExecutionSessionRef,\n  executionContextFor,\n  readDshSessionBinding,\n  resolveProcessHarnessDir,\n  resumeExecutionSession,\n} from '@mstar-harness/engine'\nimport type { ExecutionSessionRef } from '@mstar-harness/engine'\nimport { executeCommand, getCommandDefinitions, getCommandSchemas, refusalEnvelope } from '@mstar-harness/commands'\nimport type {\n  CommandDefinition,\n  CommandEffects,\n  CommandEnvelope,\n  CommandRequirement,\n  CommandSchemaDescriptor,\n  InvocationContext,\n} from '@mstar-harness/commands'\nimport { iterationViolationView, sessionCwdOf } from './_shared.ts'\nimport { validateAuditDoc } from './seams.ts'\nimport { coordinatorIdentityFor, isLeafSeatHeader } from './leaf-seat.ts'\nimport { adoptExecutionBinding, refusalOf } from './workflow-selection.ts'\nimport { clearExecutionSessionBinding } from './execution-session.ts'\nimport { clearExecutionBindingRoot, executionBindingRootOf, recordExecutionBindingRoot } from './execution-binding-roots.ts'\n\n/**\n * The ONE native command tool. `plan.bind` is here as the PRODUCER of the dsh\n * durable record (the `executionBinding` slot + the adoption receipt); the\n * other six writable commands are MCP `action`s and stay there.\n */\nconst NATIVE_COMMAND_ID = 'plan.bind'\n\n/** The tool name for one command id — the same mapping the MCP route uses. */\nexport function nativeCommandToolName(commandId: string): string {\n  return `mstar_${commandId.replace(/[.-]/g, '_')}`\n}\n\n/**\n * The caller identity of one tool execution: `exec.agent.id` (ADR constraint\n * 1 — a dsh agent's identity and its session identity are the same value).\n */\nfunction callerSessionIdOf(exec: ToolExecution): string {\n  const id = (exec.agent as { id?: unknown } | null | undefined)?.id\n  if (typeof id !== 'string' || id.trim() === '') {\n    throw new Error('the native mstar command tools require a calling agent identity (exec.agent.id); none is present on this execution')\n  }\n  return id\n}\n\n/**\n * The session header the leaf-seat contract reads — the agent shape the host\n * exposes on every tool execution (`agent.session.header`), never a\n * model-supplied argument.\n */\nfunction sessionHeaderOf(exec: ToolExecution): unknown {\n  return (exec.agent as { session?: { header?: unknown } } | null | undefined)?.session?.header\n}\n\n/**\n * The fail-closed leaf-seat refusal (the shared `leaf-seat.ts` contract): a\n * known leaf seat can never own a coordinator seat or an execution binding —\n * the named guard the removed execution-session command enforced, restored on\n * this surface before any admission or engine round-trip. The recovery names\n * the actual cause and the supported way out (run it as the coordinating\n * session; a leaf seat never needs a binding).\n */\nfunction leafSeatRefusal(command: string): CommandEnvelope<never> {\n  return refusalEnvelope({\n    command,\n    status: 'refused',\n    code: `${command}.leaf-seat`,\n    exitCode: 1,\n    message: 'known leaf sessions cannot adopt, clear, or run on any operation',\n    recovery:\n      'This seat is a leaf (session header origin \"subagent\" or a delegationDepth > 0); coordinator seats and execution bindings belong to non-leaf sessions — run the operation as the coordinating session itself, or continue without an execution binding.',\n  })\n}\n\n/**\n * Effects for the native surface: none. The shared implementation owns every\n * process/dashboard/browser effect; this surface provides refusing stubs so\n * an effect-taking command refuses by construction instead of reaching a\n * shell (the no-shell guarantee is the absence of the capability, not a rule\n * about it).\n */\nconst NATIVE_EFFECTS: CommandEffects = {\n  readInput: () => {\n    throw new Error('the stdin effect is not available on the dsh native command surface (no shell, no child process)')\n  },\n  spawn: () => {\n    throw new Error('the process effect is not available on the dsh native command surface (no shell, no child process)')\n  },\n  startDashboard: () => {\n    throw new Error('the dashboard effect is not available on the dsh native command surface')\n  },\n  openBrowser: () => {\n    throw new Error('the browser effect is not available on the dsh native command surface')\n  },\n}\n\n/**\n * The invocation context for one admitted command call: the session's\n * workspace cwd, the resolver's harness dir as the control root, and the\n * caller identity from `exec.agent.id` — never from the arguments.\n */\nfunction invocationContextOf(exec: ToolExecution, resolver: { forAgent(agent: unknown): string | null }): InvocationContext {\n  const cwd = sessionCwdOf(exec.agent)\n  if (cwd === undefined) {\n    throw new Error('the native mstar command tools require a session workspace (session.header.cwd); none is present on this execution')\n  }\n  return {\n    cwd,\n    controlRoot: resolver.forAgent(exec.agent),\n    host: 'dsh',\n    sessionId: callerSessionIdOf(exec),\n    versions: { engine: null, cli: null, plugin: null, host: 'dsh', platform: 'dsh' },\n    signal: exec.signal,\n    effects: NATIVE_EFFECTS,\n  }\n}\n\n/**\n * The description length cap for one mechanically derived payload summary\n * (the model face stays bounded even for wide payloads like `issue.add`).\n */\nconst PAYLOAD_SUMMARY_CAP = 1000\n\n/**\n * The scalar/structural type label of one published JSON Schema node,\n * mechanically read from the node itself (never hand-written per command).\n * A `$ref` is not resolved — the label stays at the node's own shape.\n */\nfunction payloadTypeOf(node: unknown, depth: number): string {\n  if (node === null || typeof node !== 'object' || Array.isArray(node)) return 'json'\n  const record = node as Record<string, unknown>\n  if (Array.isArray(record.oneOf)) {\n    return `(${record.oneOf.map((branch) => payloadTypeOf(branch, depth)).join(' | ')})`\n  }\n  const type = typeof record.type === 'string' ? record.type : undefined\n  if (type === 'object' && depth < 2) return compactPayloadSummary(record, depth + 1) ?? 'object'\n  if (type === 'array') return `${payloadTypeOf(record.items, depth + 1)}[]`\n  return type ?? 'json'\n}\n\n/**\n * The compact member summary of one published JSON Schema node: required\n * members unmarked, optional members suffixed `?`, nested objects expanded\n * one level (depth-capped), unions listed branch-by-branch. The source is\n * ALWAYS the published schema — the payload descriptor's own JSON Schema when\n * the input node is a permissive placeholder (the issue payloads), else the\n * input node itself (the shaped fields like `plan complete`'s evidence).\n */\nfunction compactPayloadSummary(node: unknown, depth = 0): string | undefined {\n  if (node === null || typeof node !== 'object' || Array.isArray(node)) return undefined\n  const record = node as Record<string, unknown>\n  if (Array.isArray(record.oneOf)) {\n    const branches = record.oneOf\n      .map((branch) => compactPayloadSummary(branch, depth + 1) ?? payloadTypeOf(branch, depth + 1))\n      .filter((branch): branch is string => branch !== undefined)\n    if (branches.length === 0) return undefined\n    return capPayloadSummary(`one of: ${branches.join(' | ')}`)\n  }\n  const properties = record.properties\n  if (properties === null || typeof properties !== 'object' || Array.isArray(properties)) return undefined\n  const required = Array.isArray(record.required)\n    ? record.required.filter((entry): entry is string => typeof entry === 'string')\n    : []\n  const members = Object.entries(properties as Record<string, unknown>).map(([name, child]) =>\n    `${name}: ${payloadTypeOf(child, depth)}${required.includes(name) ? '' : '?'}`,\n  )\n  if (members.length === 0) return undefined\n  return capPayloadSummary(`object { ${members.join(', ')} }`)\n}\n\n/** Truncate an overlong summary on the member boundary the cap leaves. */\nfunction capPayloadSummary(summary: string): string {\n  if (summary.length <= PAYLOAD_SUMMARY_CAP) return summary\n  return `${summary.slice(0, PAYLOAD_SUMMARY_CAP)}…`\n}\n\n/**\n * The object branches of a published root schema's `anyOf` union, or\n * `undefined` when the schema is not a union of objects. Read mechanically\n * from the published JSON Schema — the same source every transport serves.\n */\nfunction unionObjectBranches(jsonSchema: Record<string, unknown> | null | undefined): Array<Record<string, unknown>> | undefined {\n  if (jsonSchema === null || typeof jsonSchema !== \"object\") return undefined;\n  const branches = jsonSchema.anyOf;\n  if (!Array.isArray(branches) || branches.length === 0) return undefined;\n  const objects = branches.filter((branch): branch is Record<string, unknown> =>\n    branch !== null && typeof branch === \"object\" && !Array.isArray(branch) &&\n    branch.properties !== null && typeof branch.properties === \"object\",\n  );\n  return objects.length === branches.length ? objects : undefined;\n}\n\n/**\n * The fields every object branch of a root union declares, typed from the\n * first branch's own nodes (the mechanical projection of a union schema\n * into one callable parameter table — `issue.close`'s terminal dispositions\n * share one field set and differ only in which fields each branch\n * requires).\n */\nfunction unionPropertiesOf(branches: Array<Record<string, unknown>>): Record<string, Record<string, unknown>> {\n  if (branches.length === 0) return {};\n  const first = branches[0]!.properties as Record<string, Record<string, unknown>>;\n  let common = Object.keys(first);\n  for (const branch of branches.slice(1)) {\n    const keys = Object.keys(branch.properties as Record<string, unknown>);\n    common = common.filter((key) => keys.includes(key));\n  }\n  return Object.fromEntries(common.map((key) => [key, first[key]!]));\n}\n\n/** The branch labels of a union: the const-valued property naming the branch (`disposition=resolved`), else `default`. */\nfunction unionBranchLabel(branch: Record<string, unknown>): string {\n  for (const property of Object.values(branch.properties as Record<string, unknown>)) {\n    if (property !== null && typeof property === \"object\" && !Array.isArray(property)) {\n      const value = (property as Record<string, unknown>).const;\n      if (typeof value === \"string\") return value;\n    }\n  }\n  return \"default\";\n}\n\n/** The branch-required names of one union object branch. */\nfunction unionBranchRequired(branch: Record<string, unknown>): string[] {\n  return Array.isArray(branch.required)\n    ? branch.required.filter((entry): entry is string => typeof entry === \"string\")\n    : [];\n}\n\n/**\n * The branch-varying requirement text for one projected union field: the\n * branches that require it (labeled by their const value) versus the\n * branches that leave it optional. A field every branch requires — or none —\n * is already covered by the top-level required table and gains no text, so\n * the description stays help-first and the union text only fills the\n * per-branch gap a flat table cannot express.\n */\nfunction unionFieldRequirement(branches: Array<Record<string, unknown>>, field: string): string | undefined {\n  const requiring = branches.filter((branch) => unionBranchRequired(branch).includes(field));\n  if (requiring.length === 0 || requiring.length === branches.length) return undefined;\n  const rest = branches.filter((branch) => !requiring.includes(branch));\n  const labels = (list: Array<Record<string, unknown>>): string => [...new Set(list.map(unionBranchLabel))].join(\"|\");\n  return `required on ${labels(requiring)}; optional on ${labels(rest)}`;\n}\n\n/**\n * The dsh parameter spec for one command, mirrored MECHANICALLY from the\n * command's own published JSON Schema (the single source both transports\n * already serve) with the `sessionId` context selector removed. Scalars keep\n * their type so the model face is typed; every object/union payload stays the\n * annotation-only `json` node — the semantic validation is the shared\n * admission's, never duplicated here. A `json` node whose published schema is\n * an object with members (or a oneOf) gains a mechanically derived\n * `description` naming those members and their types, so a caller can\n * construct a valid payload without guessing at the flattened shape. A root\n * schema that is a UNION of objects (`issue.close`'s terminal dispositions —\n * no top-level `properties`) projects the fields every branch declares into\n * the same table, with each branch's own required set carried as description\n * text instead of a second validation layer.\n */\nfunction parameterSpecOf(descriptor: CommandSchemaDescriptor): Record<string, import('@deepseek-ai/dsh-tools').ParameterPropertySpec> {\n  const jsonSchema = descriptor.input as Record<string, unknown> | null | undefined;\n  const branches = unionObjectBranches(jsonSchema);\n  const rootProperties = jsonSchema !== null && typeof jsonSchema === \"object\" &&\n      jsonSchema.properties !== null && typeof jsonSchema.properties === \"object\"\n    ? jsonSchema.properties as Record<string, Record<string, unknown>>\n    : unionPropertiesOf(branches ?? []);\n  // The Map generics are anchored on the imported `CommandRequirement` (the\n  // real export), not inferred through the constructor: an unparameterized\n  // `new Map(...)` falls back to `{}` when the entry-tuple inference fails,\n  // which untypes `.help` below.\n  const helpByName = new Map<string, CommandRequirement>(\n    descriptor.requirements\n      .filter((entry) => entry.ownership === 'caller')\n      .map((entry): [string, CommandRequirement] => [entry.name, entry]),\n  )\n  const spec: Record<string, import('@deepseek-ai/dsh-tools').ParameterPropertySpec> = {}\n  for (const [field, node] of Object.entries(rootProperties)) {\n    // The session selector is transport-resolved (exec.agent.id here), never\n    // a published tool parameter (ADR constraints 1–3).\n    if (field === 'sessionId') continue\n    const nodeType = typeof node.type === \"string\" ? node.type : undefined;\n    const scalar = nodeType === 'string' ? { type: 'string' as const }\n      : nodeType === 'integer' ? { type: 'integer' as const }\n      : nodeType === 'number' ? { type: 'number' as const }\n      : nodeType === 'boolean' ? { type: 'boolean' as const }\n      : { type: 'json' as const }\n    const help = helpByName.get(field)?.help\n    const summary = scalar.type === 'json'\n      ? compactPayloadSummary(Object.hasOwn(descriptor.payloadSchemas, field) ? descriptor.payloadSchemas[field] : node)\n      : undefined\n    const branchText = branches === undefined ? undefined : unionFieldRequirement(branches, field)\n    const description = [help, branchText, summary === undefined ? undefined : `Payload: ${summary}.`]\n      .filter((part): part is string => part !== undefined)\n      .join(' — ')\n    spec[field] = {\n      ...scalar,\n      ...(description === '' ? {} : { description }),\n      ...(descriptor.required.includes(field) ? { required: true as const } : {}),\n    }\n  }\n  return spec\n}\n\n/** One-line summary of a command envelope for the model-facing render. */\nfunction envelopeSummary(commandId: string, envelope: CommandEnvelope): string {\n  if (envelope.status === 'ok') return `${commandId}: ok (exit ${envelope.exitCode})`\n  return `${commandId}: ${envelope.status} ${envelope.code} (exit ${envelope.exitCode}) — ${envelope.message}`\n}\n\n/**\n * The lossless-JSON value domain the dsh-tools seam accepts as a canonical\n * value (the `json` output node's value domain).\n */\ntype JsonValue = import('@deepseek-ai/dsh-util-values').JsonValue\n\n/**\n * Project an envelope onto the tool's canonical value: the dsh-tools seam\n * requires lossless JSON, and a shared envelope may carry `undefined` members\n * (e.g. a refusal `details.actual` that is absent). The JSON round-trip is the\n * SAME projection every other transport applies when it serializes the\n * envelope (the CLI writes it, MCP returns it as structured content) — the\n * content is untouched, only the lossy-for-JSON members go.\n */\nfunction toCanonicalValue(envelope: CommandEnvelope): JsonValue {\n  return JSON.parse(JSON.stringify(envelope)) as JsonValue\n}\n\n/**\n * The engine session reference inside a successful `plan bind` envelope: both\n * bind arms (execution and resume) answer the engine's\n * `ExecutionRead<ExecutionSessionRef>` receipt as the envelope `data`, whose\n * `data` member is the canonical ref. `undefined` — not a recognizable bind\n * receipt (a shared-command shape drift) — is never guessed into a ref.\n */\nfunction bindReceiptRefOf(envelope: CommandEnvelope): ExecutionSessionRef | undefined {\n  if (envelope.status !== 'ok') return undefined\n  const receipt = (envelope as { data?: unknown }).data\n  const candidate = (\n    typeof receipt === 'object' && receipt !== null ? (receipt as Record<string, unknown>).data : undefined\n  ) as ExecutionSessionRef | undefined\n  if (typeof candidate !== 'object' || candidate === null) return undefined\n  // The engine's own canonical-value validation (the same acceptance the wire\n  // transport applies) — a drifted receipt is never adopted.\n  try {\n    encodeExecutionSessionRef(candidate)\n  } catch {\n    return undefined\n  }\n  return candidate\n}\n\n/**\n * The workflow a `plan.bind` call addressed, for a refusal whose bind receipt\n * could not be read: the explicit `workflow` selector, else the workflow named\n * by the caller-supplied `resumeRef` (both bind arms require one of the two,\n * and the shared admission decodes the reference before committing).\n */\nfunction bindWorkflowIdOf(input: Record<string, unknown>): string | undefined {\n  if (typeof input.workflow === 'string' && input.workflow.trim() !== '') return input.workflow\n  if (typeof input.resumeRef !== 'string') return undefined\n  try {\n    return decodeExecutionSessionRef(input.resumeRef).workflowId\n  } catch {\n    return undefined\n  }\n}\n\n/**\n * The workspace the session's durable records are keyed to, when the store\n * answered `cwd-mismatch` — one extra engine read on the adoption's FAILURE\n * path only (the successful path never pays it). The recorded fact is what\n * makes \"run the resume re-bind from the workspace the durable selection is\n * recorded under\" a fact the caller can act on instead of a condition it\n * cannot see.\n */\nfunction recordedCwdOf(harnessDir: string, sessionId: string, cwd: string): string | undefined {\n  const read = readDshSessionBinding({ harnessDir }, sessionId, cwd)\n  return read.kind === 'unavailable' && read.reason === 'cwd-mismatch' ? read.recordedCwd : undefined\n}\n\n/**\n * The stage of the POST-COMMIT adoption that refused. Both run only after the\n * shared `plan.bind` returned `ok`, so the engine seat is bound either way —\n * but the two failures have DIFFERENT recoveries and must never be conflated:\n * a refused resume rejects the very reference the resume re-bind would carry,\n * while a refused slot write leaves a resumable seat behind.\n */\nexport type AdoptionFailureStage = 'resume' | 'durable-slot'\n\n/**\n * The facts a POST-COMMIT adoption refusal carries under `data`, so the\n * recovery it names is performable without the durable slot it could not\n * write. Every member is optional because each refusal knows a different\n * subset: the minted reference is absent when the bind envelope itself was\n * unreadable, and the control root is absent when the adoption could not\n * resolve one (a defensive branch no committed bind reaches).\n */\ntype AdoptionRefusalFacts = Readonly<{\n  /** The engine-minted session reference, in the wire shape the bind accepts back as `resumeRef`. */\n  ref?: ExecutionSessionRef\n  workflowId?: string\n  /** The control root the engine bind committed in — `plan.bind`'s own root, never the plugin's probe. */\n  harness?: string\n  /** The workspace the session's durable records are keyed to, when the store answered `cwd-mismatch`. */\n  recordedCwd?: string\n}>\n\n/**\n * The dsh-side adoption refusal: the engine coordinator seat the bind\n * committed stays bound, the durable slot is NOT written, and the text names\n * the actual cause plus the recovery for the stage that failed (see\n * {@link adoptionRecoveryText}). A refusal built AFTER the commit additionally\n * states that the seat is bound (`committed`) and carries\n * {@link AdoptionRefusalFacts} under `data`, so the recovery it names is\n * performable without the slot it could not write. The extra members sit\n * beside the shared refusal shape — the shared `CommandEnvelope` contract and\n * every other command's refusals are untouched.\n */\nfunction adoptionRefusal(\n  code: string,\n  message: string,\n  recovery: string,\n  facts?: AdoptionRefusalFacts,\n): CommandEnvelope<never> {\n  const refusal = refusalEnvelope({ command: 'plan.bind', status: 'refused', code, exitCode: 1, message, recovery })\n  if (facts === undefined) return refusal\n  const data = {\n    ...(facts.ref === undefined ? {} : { resumeRef: encodeExecutionSessionRef(facts.ref) }),\n    ...(facts.workflowId === undefined ? {} : { workflowId: facts.workflowId }),\n    ...(facts.harness === undefined ? {} : { harness: facts.harness }),\n    ...(facts.recordedCwd === undefined ? {} : { recordedCwd: facts.recordedCwd }),\n  }\n  return Object.assign(\n    refusal as CommandEnvelope<never> & { committed?: true; data?: unknown },\n    { committed: true as const, ...(Object.keys(data).length === 0 ? {} : { data }) },\n  )\n}\n\n/**\n * The recovery of a POST-COMMIT adoption refusal, selected by the stage that\n * failed. Pure and exported for the stage regression: the two arms must not\n * advertise the same route.\n *\n * - `resume`: the engine refused its own minted reference (or the resumed\n *   reference did not match the caller). Re-running the same resume re-bind\n *   presents exactly that refused value, so it loops — the engine's own\n *   coordinator recovery (`mstar session recover`, which replaces a recorded\n *   stopped/stale holder after operator attestation) is the way out.\n * - `durable-slot`: the engine resume succeeded and only the dsh slot write\n *   failed, so the resume re-bind re-adopts. When the store reported\n *   `cwd-mismatch`, the recovery names the RECORDED workspace (the durable key\n *   is the session id AND the workspace), as carried in `data.recordedCwd`.\n */\nexport function adoptionRecoveryText(\n  stage: AdoptionFailureStage,\n  causeCode: string,\n  recordedCwd?: string,\n): string {\n  if (stage === 'resume') {\n    return 'The engine coordinator seat from the bind stays BOUND, but the durable execution binding slot was NOT written: ' +\n      `the engine refused to resume this session reference (${causeCode}), so the resume re-bind that re-adopts is not available. ` +\n      'Recover the seat through the engine\\'s own coordinator recovery: run `mstar session recover --workflow <workflow-id> ' +\n      '--prior-session <session-id> --reason <text> --attestation <path> --expect <token> --operation <id>` ' +\n      '(both ids are carried in this refusal\\'s `data.resumeRef`; use `--unowned=true` instead of `--prior-session` when the ' +\n      'workflow records no coordinator row), then re-run the bind.'\n  }\n  const workspace = recordedCwd === undefined\n    ? 'run from the session workspace the durable selection is recorded under'\n    : `run from the RECORDED workspace carried in \\`data.recordedCwd\\` (${recordedCwd}) — the workspace this session's durable records are keyed to`\n  return 'The engine coordinator seat from the bind stays BOUND and a plain re-execution bind is refused (a live ACTIVE holder is never replaced). ' +\n    'Recovery: re-run the native bind as a resume carrying this refusal\\'s `data.resumeRef` as `resumeRef`, with the SAME `harness` selection ' +\n    `(\\`data.harness\\` names the control root the engine bound in) — ${workspace}. The resume re-adopts the binding slot.`\n}\n\n/**\n * The facts a PRE-SLOT post-commit refusal answers with: each arm is reached\n * only after the engine bind committed and before the durable slot write, so\n * every arm leaves the seat BOUND and must carry the facts its own recovery\n * names.\n */\nexport type PostCommitAdoptionFailure =\n  | { kind: 'receipt-unrecognizable'; sessionId: string; workflowId?: string }\n  | { kind: 'no-harness'; ref: ExecutionSessionRef }\n  | { kind: 'foreign-reference'; ref: ExecutionSessionRef; sessionId: string }\n\n/**\n * The three refusals of a committed bind that never reached the durable slot\n * write. Pure and exported for the refusal regression: a real engine mints a\n * readable reference naming the carrying session, so no fixture can produce\n * these arms — the selection itself is what the contract is pinned on.\n */\nexport function postCommitAdoptionRefusal(failure: PostCommitAdoptionFailure): CommandEnvelope<never> {\n  if (failure.kind === 'receipt-unrecognizable') {\n    // The engine bind committed, but its envelope carried no readable\n    // reference, so the durable slot cannot be written and the resume re-bind\n    // has nothing to carry. A plain re-execution bind is refused while the\n    // live holder exists — the engine's own coordinator recovery is the way\n    // out (it replaces the recorded holder after operator attestation).\n    const workflow = failure.workflowId ?? '<workflow-id>'\n    return adoptionRefusal(\n      'binding.receipt-unrecognizable',\n      'the plan bind envelope carried no recognizable execution session reference — the execution binding was NOT adopted',\n      'The engine coordinator seat from the bind stays BOUND (a live ACTIVE holder is never replaced by a bind), but the durable execution binding slot was NOT written: ' +\n        'this build could not read the minted reference back out of the bind receipt. ' +\n        `Recover the seat through the engine's own coordinator recovery: run \\`mstar session recover --workflow ${workflow} ` +\n        `--prior-session ${failure.sessionId} --reason <text> --attestation <path> --expect <token> --operation <id>\\` ` +\n        '(use `--unowned=true` instead of `--prior-session` when the workflow records no coordinator row), then re-run the bind.',\n      { ...(failure.workflowId === undefined ? {} : { workflowId: failure.workflowId }) },\n    )\n  }\n  if (failure.kind === 'no-harness') {\n    // DEFENSIVE, not part of the normal contract: the shared admission refuses\n    // a null root before committing, so a committed bind reaches this arm only\n    // when the root facts changed between the bind and the adoption (the\n    // variable removed, a `.mstar`/`.mstarc` declaration created or removed,\n    // or the git worktree changed). It therefore must not tell the caller to\n    // \"re-run the bind\" — that bind is refused — so it carries the minted\n    // reference and names the engine's coordinator recovery instead.\n    return adoptionRefusal(\n      'binding.no-harness',\n      'the carrying session has no resolved control root or workspace — the execution binding was NOT adopted',\n      'The engine coordinator seat from the bind stays BOUND, but the durable execution binding slot was NOT written: this adoption could not resolve the control root the shared bind committed in. ' +\n        `Recover the seat through the engine's own coordinator recovery: run \\`mstar session recover --workflow ${failure.ref.workflowId} ` +\n        `--prior-session ${failure.ref.sessionId} --reason <text> --attestation <path> --expect <token> --operation <id>\\` ` +\n        '(use `--unowned=true` instead of `--prior-session` when the workflow records no coordinator row), then re-run the bind.',\n      { ref: failure.ref, workflowId: failure.ref.workflowId },\n    )\n  }\n  // The reference names a session other than the caller: adopting it would\n  // bind another session's seat, and no re-bind can make it adoptable. It is\n  // still a POST-COMMIT refusal — the engine bind committed — so it states\n  // that fact with no `data`: nothing read here would make a recovery\n  // performable.\n  return adoptionRefusal(\n    'binding.foreign-reference',\n    `the bound session reference names ${failure.ref.sessionId}, not the carrying session ${failure.sessionId} — the execution binding was NOT adopted`,\n    'Run the bind as the carrying session itself; a reference to another session is never adoptable.',\n    {},\n  )\n}\n\n/**\n * Task 3 (#527): persist the durable `executionBinding` slot after a native\n * `plan bind` succeeds — the adoption the removed slash command performed,\n * kept on the native path. The binding order's durable-selection\n * rung and the workflow ledger's explicit route\n * (`resolveExecutionLedgerTarget`) read exactly this slot, so ledger\n * attribution works with no slash command.\n *\n * The validation set is the slash command's, unchanged:\n * the reference must name the carrying session, the ENGINE resume must\n * succeed BEFORE the slot write (a foreign, copied, stale-epoch or\n * scope-mismatched reference is refused and never adopted), and the write\n * goes through `adoptExecutionBinding` — the session's user selection is\n * preserved and the exclusion floor merges by max. The adoption target is the\n * root the SHARED ADMISSION bound in — `resolveProcessHarnessDir(cwd,\n * callHarness)`, the one resolution both `plan.bind` arms perform before\n * committing (the explicit per-call `harness` when non-blank, the\n * git-top-level/workspace probe otherwise) — never the plugin's own\n * workspace-only probe: the two answers can differ (a session whose cwd is a\n * subdirectory of the repository declaring the harness, or a linked worktree),\n * and the adoption must resume and persist its slot in the store the engine\n * actually wrote. An adoption failure returns a refused envelope carrying the\n * engine's own code/message verbatim plus the recovery for the stage that\n * failed; the command itself already committed engine-side.\n */\nasync function adoptNativeExecutionBinding(\n  envelope: CommandEnvelope,\n  input: Record<string, unknown>,\n  exec: ToolExecution,\n): Promise<CommandEnvelope> {\n  // A refused (or usage) bind IS the engine's verdict — a stale epoch, a\n  // foreign store, a scope mismatch, a missing coordinator seat — and the\n  // \"engine refusals surface verbatim\" contract covers it: return the\n  // incoming envelope unchanged BEFORE the bind-arm narrowing, so a refused\n  // bind is never rewritten as a dsh-side adoption refusal.\n  if (envelope.status !== 'ok') return envelope\n  // Both bind arms adopt: the execution bind (the engine minted the ref) and\n  // the resume bind (the caller supplied a reference). Any other command\n  // input never reaches the envelope's bind arms, so this narrow check is\n  // exact.\n  if (input.execution !== true && input.resumeRef === undefined) return envelope\n  // `exec.agent.id` is guaranteed by `invocationContextOf` (it throws before\n  // any admission without one); every refusal below names the holder it is\n  // actually leaving bound.\n  const sessionId = callerSessionIdOf(exec)\n  const ref = bindReceiptRefOf(envelope)\n  if (ref === undefined) {\n    // POST-COMMIT: the workflow is still derivable from the bind input.\n    return postCommitAdoptionRefusal({\n      kind: 'receipt-unrecognizable',\n      sessionId,\n      workflowId: bindWorkflowIdOf(input),\n    })\n  }\n  // The adoption target is the root the shared admission bound in. Both\n  // `plan.bind` arms resolve it as `resolveProcessHarnessDir(cwd,\n  // input.harness)` and refuse `null` BEFORE committing, so a committed bind\n  // has a non-null root and this call answers the same one: an explicit\n  // non-blank `harness` is resolved against the same cwd base (the shared\n  // `callHarness` narrowing), and the implicit arm uses the engine's\n  // git-top-level/main-worktree probe (which also honours `MSTAR_HARNESS_DIR`)\n  // — NOT the plugin's workspace-only probe, whose null answer for a\n  // subdirectory session used to turn a committed bind into a bare\n  // `binding.no-harness` refusal. A relative selector keeps resolving to the\n  // same absolute root the engine recorded.\n  const cwd = sessionCwdOf(exec.agent)\n  const callHarness = typeof input.harness === 'string' && input.harness.trim() !== '' ? input.harness : undefined\n  let harnessDir: string | null = null\n  try {\n    harnessDir = cwd === undefined ? null : resolveProcessHarnessDir(cwd, callHarness)\n  } catch {\n    // The same resolution that could throw here (the linked-checkout Git\n    // verdict) would have thrown in the shared admission instead of committing,\n    // so reaching this is the defensive case below — answer the refusal that\n    // carries the minted reference rather than escaping as a tool error.\n    harnessDir = null\n  }\n  if (harnessDir === null || cwd === undefined) {\n    return postCommitAdoptionRefusal({ kind: 'no-harness', ref })\n  }\n  // The reference names the carrying session — the same first check the slash\n  // adoption made, before any engine round-trip.\n  if (ref.sessionId !== sessionId) {\n    return postCommitAdoptionRefusal({ kind: 'foreign-reference', ref, sessionId })\n  }\n  // Which post-commit step failed decides the recovery: the engine resume\n  // rejecting the reference cannot be recovered by presenting that same\n  // reference again.\n  let stage: AdoptionFailureStage = 'resume'\n  try {\n    // The engine resume succeeds BEFORE the slot write: a copied store id, a\n    // stale epoch or a scope mismatch refuses here and NOTHING is adopted.\n    // The identity is built by the shared leaf module, which ATTESTS the leaf\n    // fact from the same predicate the pre-admission check above reads — the\n    // engine's `coordination.leaf-seat` receiver stays defense-in-depth.\n    const resumed = await resumeExecutionSession(\n      executionContextFor({ harnessDir }, coordinatorIdentityFor(sessionHeaderOf(exec), sessionId, ref.workflowId)),\n      ref,\n    )\n    if (resumed.data.sessionId !== sessionId || resumed.data.workflowId !== ref.workflowId) {\n      throw new Error('the resumed execution session did not match the carrying session')\n    }\n    stage = 'durable-slot'\n    const adopted = adoptExecutionBinding(\n      harnessDir,\n      sessionId,\n      cwd,\n      { version: 1, harnessRoot: harnessDir, session: ref },\n      { storeId: resumed.storeId, epoch: resumed.epoch },\n    )\n    if (!adopted) throw new Error('the execution binding store refused the adoption write')\n    // The adoption receipt: the consumers (ledger attribution, the native\n    // clear) resolve THIS root for the session instead of re-deriving the\n    // workspace harness — the durable slot lives here, and nothing is ever\n    // copied into the workspace root. Only a successful adoption records.\n    // Awaited so `ok` means the receipt is durable, not only in memory; the\n    // returned promise never rejects (the seam logs the cause), so a refused\n    // durable write stays non-fatal and cannot fail the committed bind.\n    await recordExecutionBindingRoot(sessionId, cwd, harnessDir)\n  } catch (error) {\n    // The engine's own refusal code/message surface verbatim. The seat the\n    // bind committed stays bound and the durable slot is exactly what this\n    // path failed to write, so the refusal must carry the minted reference —\n    // otherwise its own recovery is unperformable. The recovery itself depends\n    // on the stage (see `adoptionRecoveryText`).\n    const { code, message } = refusalOf(error)\n    // One extra engine read, on this failure path only, to learn the workspace\n    // the durable records are keyed to when the store refused the pair: the\n    // refusal's recovery can then name it instead of describing a condition\n    // the caller cannot see.\n    const recordedCwd = stage === 'durable-slot' ? recordedCwdOf(harnessDir, sessionId, cwd) : undefined\n    return adoptionRefusal(code, message, adoptionRecoveryText(stage, code, recordedCwd), {\n      ref,\n      workflowId: ref.workflowId,\n      harness: harnessDir,\n      ...(recordedCwd === undefined ? {} : { recordedCwd }),\n    })\n  }\n  return envelope\n}\n\n/** Build the native tool for one shared command definition. */\nfunction nativeCommandTool(\n  definition: CommandDefinition,\n  resolver: { forAgent(agent: unknown): string | null },\n) {\n  const descriptor = getCommandSchemas([definition])[0]!\n  const commandId = definition.id\n  const required = descriptor.required.length === 0 ? '' : ` Required inputs: ${descriptor.required.join(', ')}.`\n  return defineTool({\n    name: nativeCommandToolName(commandId),\n    description:\n      `${definition.description} Command id: ${commandId}.${required} ` +\n      'The sessionId is injected from the calling agent identity (exec.agent.id) and a session id argument is ignored; ' +\n      'engine refusals surface verbatim in the returned envelope (status refused/usage + message + recovery).',\n    parameters: parameterSpecOf(descriptor),\n    output: {\n      schema: { type: 'json' },\n      render: (_args, value) => [{ type: 'text', text: envelopeSummary(commandId, value as CommandEnvelope) }],\n    },\n    presentCall: args => ({\n      card: 'generic',\n      title: `Command ${commandId}`,\n      kind: 'other',\n      rawInput: JSON.stringify(args)?.slice(0, 160) ?? '',\n    }),\n    // Every command here mutates the execution authority — exclusive (never\n    // parallel with siblings), matching the read-only tools' registry default.\n    isConcurrencySafe: () => false,\n    async execute(args, exec) {\n      // Fail-closed leaf guard FIRST: `plan bind` is the command that mints a\n      // coordinator seat, and a known leaf seat can never own one — refuse\n      // before any admission or engine round-trip.\n      if (isLeafSeatHeader(sessionHeaderOf(exec))) {\n        return toCanonicalValue(leafSeatRefusal(commandId))\n      }\n      const input = args as Record<string, unknown>\n      // Identity is never model-supplied: strip the session selector before\n      // admission so the shared admission resolves it from the injected\n      // context (exec.agent.id) instead of an argument value.\n      const { sessionId: _ignored, ...commandInput } = input\n      const envelope = await executeCommand(commandId, commandInput, invocationContextOf(exec, resolver))\n      // The durable adoption runs on every bind arm; `adoptNativeExecutionBinding`\n      // returns the envelope untouched when the input carries neither\n      // `execution: true` nor a `resumeRef`, and a refused bind is never rewritten.\n      return toCanonicalValue(await adoptNativeExecutionBinding(envelope, commandInput, exec))\n    },\n  })\n}\n\n/**\n * The logical command id the native clear reports in its envelope. There is\n * no shared `execution.clear` command to map through a command tool — the\n * clear is a dsh-native tool wrapping the dsh-side binding internals, so its\n * envelope is assembled here with the same shape the shared commands answer.\n */\nconst EXECUTION_CLEAR_COMMAND = 'execution.clear'\n\n/** The ok envelope of a completed clear (the shared commands' ok shape). */\nfunction executionClearOk(): CommandEnvelope {\n  return { version: 1, command: EXECUTION_CLEAR_COMMAND, status: 'ok', code: 'execution.clear.ok', exitCode: 0, data: null }\n}\n\n/**\n * The named no-harness refusal of the clear: the remaining case is a session\n * with no workspace at all, or one whose workspace declares no harness and\n * whose plugin config names none. The recovery names both routes that exist in\n * this build — a workspace that declares the control harness, and the plugin's\n * own `harnessDir` config (which wins over workspace probing).\n */\nfunction executionClearNoHarness(): CommandEnvelope<never> {\n  return refusalEnvelope({\n    command: EXECUTION_CLEAR_COMMAND,\n    status: 'refused',\n    code: 'execution.clear.no-harness',\n    exitCode: 1,\n    message: 'the carrying session has no resolved harness dir or workspace — the execution binding could not be read for the clear',\n    recovery: 'Open the session in the workspace that declares the control harness (.mstar/ or .mstarc), or point the plugin\\'s `harnessDir` config at the control root that holds this session\\'s binding, then re-run the clear.',\n  })\n}\n\n/**\n * The named no-binding refusal of the clear. It is TRUE for both reachable\n * cases, which is why it names neither \"nothing exists\" nor a nonexistent\n * action:\n *\n * - the resolved root genuinely holds no clearable binding for this session;\n * - the session's binding was adopted into ANOTHER control root, which the\n *   workspace probe cannot reach (the durable key is the session id AND the\n *   session workspace, and the root is whatever the bind selected).\n *\n * The recovery names the route that exists for the second case: the plugin's\n * `harnessDir` config resolves the control root directly and therefore reaches\n * a store the workspace probe answers `null` for — while the session keeps the\n * workspace the durable row is keyed to. A session that never adopted a\n * cross-root binding is the no-action case the recovery also states.\n */\nfunction executionClearNoBinding(): CommandEnvelope<never> {\n  return refusalEnvelope({\n    command: EXECUTION_CLEAR_COMMAND,\n    status: 'refused',\n    code: 'execution.clear.no-binding',\n    exitCode: 1,\n    message: 'no clearable execution binding is reachable from the control root resolved here',\n    recovery: 'This clear resolves the control root of the carrying session\\'s workspace (or the configured root), and a binding recorded in a DIFFERENT control root is not reachable from it by workspace resolution. ' +\n      'Point the plugin\\'s `harnessDir` config at that control root — the durable key is the session id AND the session workspace, which this session keeps — then re-run the clear. ' +\n      'If no cross-root binding was ever adopted, there is nothing to clear and no action is needed.',\n  })\n}\n\n/**\n * The native `mstar_execution_clear` tool: the reachability for\n * `clearExecutionBinding` after the removal of the slash command whose `clear`\n * arm was its only caller. It wraps `clearExecutionSessionBinding` (the readable\n * record guard, the nothing-to-clear guard, and the observed-generation\n * `selectedGeneration` read) with the identity from `exec.agent.id` — the\n * parameter face is EMPTY, so identity is never model-choosable. The resolved\n * root is the session's SELECTED harness (the bind adoption's receipt) when one\n * exists, the workspace harness otherwise.\n */\nfunction executionClearTool(\n  resolver: { forAgent(agent: unknown): string | null },\n) {\n  return defineTool({\n    name: 'mstar_execution_clear',\n    description:\n      \"Clear the calling session's own durable mstar execution binding — the `executionBinding` slot a successful plan bind recorded in this session's control-root store. \" +\n      'The session id comes from the calling agent identity (exec.agent.id) — there are no parameters and identity is never model-choosable; ' +\n      \"the user's workflow selection and exclusion floor are preserved. \" +\n      'Clearing a session whose binding is not reachable from the resolved control root is a named refusal (no clearable execution binding) naming the `harnessDir` config route, ' +\n      'and an unreadable or refused binding record is a refusal carrying the store reason, never a silent no-op.',\n    parameters: {},\n    output: {\n      schema: { type: 'json' },\n      render: (_args, value) => [{ type: 'text', text: envelopeSummary(EXECUTION_CLEAR_COMMAND, value as CommandEnvelope) }],\n    },\n    presentCall: args => ({\n      card: 'generic',\n      title: `Command ${EXECUTION_CLEAR_COMMAND}`,\n      kind: 'other',\n      rawInput: JSON.stringify(args)?.slice(0, 160) ?? '',\n    }),\n    // Mutates the execution authority's binding slot — exclusive.\n    isConcurrencySafe: () => false,\n    async execute(_args, exec) {\n      // The fail-closed leaf guard: a leaf seat holds no execution binding and\n      // can never hold one — refuse before reading the store. `_args` is never\n      // read: the only identity this tool acts on is `exec.agent.id`, so a\n      // model-supplied `sessionId` (or any other argument) has no effect.\n      if (isLeafSeatHeader(sessionHeaderOf(exec))) {\n        return toCanonicalValue(leafSeatRefusal(EXECUTION_CLEAR_COMMAND))\n      }\n      const cwd = sessionCwdOf(exec.agent)\n      if (cwd === undefined) {\n        return toCanonicalValue(executionClearNoHarness())\n      }\n      // The clear resolves the session's SELECTED harness (the root the bind\n      // adoption recorded) BEFORE any workspace probe: a bind naming another\n      // control root recorded that root for this session, and clearing it must\n      // act on THAT root. Probing the workspace first refuses `no-harness` for a\n      // session that validly bound from a workspace declaring no harness — and\n      // no other clear route reaches that slot. The workspace harness only backs\n      // a session that never selected an explicit root.\n      const sessionId = callerSessionIdOf(exec)\n      const harnessDir = executionBindingRootOf(sessionId, cwd) ?? resolver.forAgent(exec.agent)\n      if (harnessDir === null) {\n        return toCanonicalValue(executionClearNoHarness())\n      }\n      const outcome = await clearExecutionSessionBinding(harnessDir, sessionId, cwd)\n      if (outcome.kind === 'cleared') {\n        // Drop the adoption receipt: the slot is gone, so a later clear resolves\n        // the workspace root instead of re-resolving a cleared slot — it answers\n        // `no-binding` when the workspace declares a harness there, and the\n        // named no-harness refusal otherwise.\n        clearExecutionBindingRoot(sessionId, cwd)\n        return toCanonicalValue(executionClearOk())\n      }\n      if (outcome.kind === 'no-binding') return toCanonicalValue(executionClearNoBinding())\n      // The store refused the durable record. When the cause is a workspace\n      // mismatch the read already knows the RECORDED workspace, so this\n      // failure path spends one extra engine read to carry it: \"the record must\n      // be readable for this session and its exact cwd\" was a key the caller\n      // could not see. Every other store refusal keeps its unchanged text.\n      const recordedCwd = outcome.reason === 'cwd-mismatch' ? recordedCwdOf(harnessDir, sessionId, cwd) : undefined\n      const refused = refusalEnvelope({\n        command: EXECUTION_CLEAR_COMMAND,\n        status: 'refused',\n        code: 'execution.clear.store-refused',\n        exitCode: 1,\n        message: `no clearable execution binding (${outcome.reason})`,\n        recovery: recordedCwd === undefined\n          ? 'Resolve the store refusal named in the message (the durable binding record must be readable and writable for this session and its exact cwd), then re-run the clear.'\n          : `This session's durable records are keyed to the workspace carried in \\`data.recordedCwd\\` (${recordedCwd}), not the workspace this clear runs from — the durable key is the session id AND the session workspace. Run the clear from that workspace (reopen the session there), or from a session whose workspace is that one, then re-run the clear.`,\n      })\n      return toCanonicalValue(recordedCwd === undefined\n        ? refused\n        : Object.assign(refused as CommandEnvelope<never> & { data?: unknown }, { data: { recordedCwd } }))\n    },\n  })\n}\n\n/** One violation row of `auditValidateTool`'s output schema — its only consumer, and not a public surface. */\nconst AUDIT_VALIDATE_VIOLATION_SCHEMA = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    severity: { type: 'string', required: true, enum: ['critical', 'high', 'medium', 'low', 'nit'] },\n    code: { type: 'string', required: true },\n    message: { type: 'string', required: true },\n    fix: { type: 'string' },\n  },\n} as const\n\n/**\n * The native `mstar_audit_validate` tool — the review-report credential scan of\n * `mstar-audit` Hard Rule 4 (`redactSecrets`), and the validator behind\n * `mstar audit scaffold`. It has NO MCP twin: the `mstar_audit` family publishes\n * `scaffold` / `secret-scan` / `supply-chain`, none of which validates a report\n * document, so removing it would remove the capability instead of folding it.\n *\n * It reuses the seam validator (`validateAuditDoc` — the SAME path the\n * fs-intent seam runs) and layers the findings summary on top: line + type only,\n * never a secret value (Hard Rule 4). A missing report file is an error result\n * naming the absolute path, not a manufactured `ok`.\n */\n\nfunction auditValidateTool() {\n  return defineTool({\n    name: 'mstar_audit_validate',\n    description:\n      'Validate a review report under {REVIEW_DIR}: the credential scan of mstar-audit Hard ' +\n      'Rule 4 (redactSecrets) — no CLI equivalent, the validator behind `mstar audit scaffold`.',\n    parameters: {\n      report_path: {\n        type: 'string',\n        required: true,\n        description: 'Review report file under `{REVIEW_DIR}`.',\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          ok: { type: 'boolean', required: true },\n          violations: { type: 'array', required: true, items: AUDIT_VALIDATE_VIOLATION_SCHEMA },\n          secrets: {\n            type: 'array',\n            required: true,\n            items: {\n              type: 'object',\n              additionalProperties: false,\n              properties: {\n                line: { type: 'integer', required: true },\n                type: { type: 'string', required: true },\n              },\n            },\n          },\n        },\n      },\n      render: (_args, value) => [\n        { type: 'text', text: `audit validate: ${value.ok ? 'PASS' : 'FAIL'} (${value.secrets.length} secret finding${value.secrets.length === 1 ? '' : 's'})` },\n      ],\n    },\n    presentCall: args => ({ card: 'generic', title: 'Validate review report', kind: 'other', rawInput: args.report_path }),\n    // Read-only evaluation — exclusive anyway (registry default).\n    isConcurrencySafe: () => false,\n    async execute(args) {\n      const abs = resolve(args.report_path)\n      if (!existsSync(abs)) throw new Error(`report file not found: ${abs}`)\n      const text = readFileSync(abs, 'utf8')\n      // Shared gate validator (validateSeamDoc → gateSeamIntent path): the\n      // credential scan. The tool layers the findings summary (line + type only —\n      // secret values are never reproduced, mstar-audit Hard Rule 4) on top.\n      const result = validateAuditDoc(text, abs)\n      return { ok: result.ok, violations: result.violations.map(iterationViolationView), secrets: result.findings }\n    },\n  })\n}\n\n/**\n * Register the native tool surface. The registrations are deferred with\n * `ctx.inject(['tools'], …)` (the optional-unit pattern, as in every tool\n * module) and each registration's disposer is returned as the inject teardown,\n * so an HMR reload of the plugin fiber unregisters the tools cleanly (a\n * post-dispose lookup finds none).\n *\n * The surface is exactly three tools (see the module header for the rule):\n * `mstar_plan_bind` (the durable-slot producer), `mstar_audit_validate` (no MCP\n * twin) and `mstar_execution_clear` (no shared command).\n * @param ctx - registrant context carrying the tool registry.\n * @param resolver - the per-workspace `{HARNESS_DIR}` resolver (the control\n * root resolves per the calling session's workspace — never the process cwd).\n */\nexport function registerNativeCommandTools(ctx: Context, resolver: { forAgent(agent: unknown): string | null }): void {\n  ctx.inject(['tools'], (toolsCtx) => {\n    const definition = getCommandDefinitions().find((candidate: CommandDefinition) => candidate.id === NATIVE_COMMAND_ID)\n    if (definition === undefined) throw new Error(`no shared command definition for the native tool: ${NATIVE_COMMAND_ID}`)\n    const disposers: Array<() => void> = [\n      toolsCtx.tools.register(nativeCommandTool(definition, resolver)),\n      toolsCtx.tools.register(auditValidateTool()),\n      toolsCtx.tools.register(executionClearTool(resolver)),\n    ]\n    return () => {\n      for (const dispose of disposers.splice(0)) dispose()\n    }\n  })\n}\n"
    },
    {
      "path": "packages/dsh/src/client/index.ts",
      "content": "/**\n * Morning Star workflow panel — dsh client plugin entry (plan sidebar §L1.3):\n * `inject` (cordis service waits) + `apply(ctx: ClientContext)`.\n *\n * On apply: creates the two panel clients over the client `connection` service\n * (the panel's data path is the host's shared `/api` typert gateway: a polled\n * store-backed snapshot, plus the picker's durable write), registers the\n * `mstar-panel` dictionaries, registers the panel as a right-Sidebar page tab type\n * (`ctx.sidebarRightTabs.register`, `kind: 'mstar-workflow'`, one guide\n * capsule at order 20), then waits for the ui-sidebar-right seat\n * declarations and registers the panel body and its chip title as keyed\n * entries under the definition's `id` — the two-stage seat contract. The old\n * conversation-area view-tab registration is gone: the sidebar tab REPLACES\n * the conversation-area tab (a migration, not a second surface).\n *\n * The client is created ONCE per apply and disposed with the fiber, so a\n * reloaded plugin starts from a clean snapshot cache. Every registration\n * sits in its own `ctx.effect` so unload disposes it.\n */\n\nimport type { Context as ClientContext } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-theme/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-sidebar/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-sidebar-right/client'\nimport { MSTAR_PANEL_ID, mstarPanelDefinition } from './panel/definition.ts'\nimport { MstarWorkflowPickerClient, type MstarWorkflowPickerConnection } from './panel/workflow-picker-client.ts'\nimport { MstarPanelSnapshotClient } from './panel/panel-snapshot-client.ts'\nimport { MstarPanelTitle } from './panel/MstarPanelTitle.tsx'\nimport { createHostThemeFace } from './panel/theme.ts'\nimport { en, NS, zh } from './panel/locale.ts'\nimport { createPanelStore } from './panel/panel-store.ts'\nimport { PanelView } from './panel/PanelView.tsx'\nimport { LinearSettingsCard, LINEAR_SETTINGS_ROW_KEY } from './linear-settings-card.tsx'\nimport { LinearSettingsStore } from './linear-settings-store.ts'\nimport { en as linearSettingsEn, NS as LINEAR_SETTINGS_NS, zh as linearSettingsZh } from './linear-settings-locale.ts'\n\n/**\n * Cordis service faces the plugin waits for (spec §4.4: slots + sessions +\n * locale + the wire + the tab-type registry). `sessions` is load-bearing as\n * the session standard scope's wait and `connection` carries the\n * engine-status transport; `sidebarRightTabs` is the registry `apply`\n * registers the page tab type into; `layout` is the panel-selection face the\n * panel's own surfaces drive (a cordis service, so it is declared here before\n * any selection can be reached).\n */\nexport const inject = ['slots', 'sessions', 'locale', 'connection', 'sidebarRightTabs', 'theme']\n\nexport function apply(ctx: ClientContext): void {\n  const connection = (ctx as unknown as {\n    connection?: MstarWorkflowPickerConnection & { isLoopback?: boolean }\n  }).connection\n  const picker = new MstarWorkflowPickerClient(connection)\n  ctx.effect(() => () => picker.dispose(), 'ui-mstar-panel: workflow picker client')\n  // The store-backed read: the panel polls `mstar/panelSnapshot` while its tab\n  // is visible (the hook drives start/stop) — the retired emission read's\n  // replacement.\n  // One RPC face, no store and no timer: nothing to dispose with the fiber.\n  const panelSnapshot = new MstarPanelSnapshotClient(connection)\n  // The host's colour SCHEME, never its palette (compass constraint 4): the\n  // product's own `--ms-*` values stay, and the scheme flips the shared\n  // `[data-ms-theme]` token block.\n  const theme = createHostThemeFace(ctx.theme, (listener) => ctx.on('theme/change', listener))\n  ctx.effect(() => () => theme.dispose(), 'ui-mstar-panel: theme bridge')\n  const themeFace = theme.face\n  const t = ctx.locale.bind(NS)\n  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'ui-mstar-panel: dictionaries')\n  ctx.effect(\n    () => ctx.sidebarRightTabs.register(mstarPanelDefinition(t)),\n    'ui-mstar-panel: tab type',\n  )\n  // The linear-mcp row's Settings card: one keyed `plugins.row.config` entry,\n  // keyed by the row the bundle patch declares. The row's native enable\n  // toggle stays the host's; this card only reads it and offers Authorize\n  // after it is on.\n  const linearSettings = new LinearSettingsStore(connection, {\n    loopback: connection?.isLoopback ?? true,\n  })\n  ctx.effect(() => () => linearSettings.dispose(), 'ui-mstar-linear-settings: card store')\n  ctx.effect(\n    () => ctx.locale.register(LINEAR_SETTINGS_NS, { zh: linearSettingsZh, en: linearSettingsEn }),\n    'ui-mstar-linear-settings: dictionaries',\n  )\n  // The slot is declared by the host's Plugins page (a different dsh package\n  // than this cohort's declared peers), so the registry is narrowed onto the\n  // one keyed-entry surface this registration consumes.\n  const pluginsRowSlots = ctx.slots as unknown as {\n    inject(name: string, factory: () => Generator<unknown, void, unknown>): () => void\n    register(\n      entry: {\n        name: string\n        key: string\n        locale: string\n        inject: () => {\n          controller: LinearSettingsStore\n          hooks: { snapshot: LinearSettingsStore['snapshot'] }\n        }\n      },\n      component: (props: never) => unknown,\n    ): () => void\n  }\n  ctx.effect(\n    () => pluginsRowSlots.inject('plugins.row.config', function* () {\n      yield pluginsRowSlots.register({\n        name: 'plugins.row.config',\n        key: LINEAR_SETTINGS_ROW_KEY,\n        locale: LINEAR_SETTINGS_NS,\n        // The renderer binds `hooks.snapshot` to the card's `useSnapshot`\n        // selector hook (the same contract the advisor card uses).\n        inject: () => ({ controller: linearSettings, hooks: { snapshot: linearSettings.snapshot } }),\n      }, LinearSettingsCard as unknown as (props: never) => unknown)\n    }),\n    'ui-mstar-linear-settings: row card',\n  )\n  // ONE entry: the session's right-pane tab. The product is per-repository state,\n  // so the host's GLOBAL panel list gets no row from this plugin — and with no\n  // global row there is no keyed `main` seat to open, and no selection call.\n  // The body seat closes over the two clients exactly as the old view-tab\n  // registration did: the transport is a plugin-level concern, never a\n  // host-supplied prop. The `store` option hands the seat the panel's\n  // entry store (plan sidebar §L2.4): the framework caches one instance per\n  // (entry, session), so the selected section survives the body's unmount\n  // while another pane tab is active.\n  const panelStore = createPanelStore()\n  ctx.effect(\n    () => ctx.slots.inject('sidebar.right.pane.tab', () => ctx.slots.register({\n      name: 'sidebar.right.pane.tab',\n      key: MSTAR_PANEL_ID,\n      locale: NS,\n      store: panelStore,\n    }, (props: Parameters<typeof PanelView>[0]) =>\n      PanelView({\n        ...props,\n        picker,\n        panelSnapshot,\n        localeFace: ctx.locale,\n        themeFace,\n      }))),\n    'ui-mstar-panel: panel body',\n  )\n  ctx.effect(\n    () => ctx.slots.inject('sidebar.right.pane.tab.title', () => ctx.slots.register({\n      name: 'sidebar.right.pane.tab.title',\n      key: MSTAR_PANEL_ID,\n    }, MstarPanelTitle)),\n    'ui-mstar-panel: panel chip title',\n  )\n}\n"
    },
    {
      "path": "packages/dsh/src/panel/panel-snapshot-endpoint.ts",
      "content": "/**\n * Host half of the panel-snapshot channel: the `mstar/panelSnapshot` endpoint\n * on the host's SHARED `/api` typert gateway.\n *\n * WHY its own service: the panel's read is the store-backed one, while the\n * `mstar` engine-status gateway serves the last MODEL EMISSION (retired as a\n * read path). Two cordis services can share the `mstar` WIRE namespace — a\n * descriptor names its own service key — so this half is independently\n * installable and withdrawable, and neither retirement can take the other's\n * endpoint with it.\n *\n * VALIDATION CHAIN — mirrored from `engine-status-endpoint.ts` (the single\n * source of this order), answered entirely BEFORE any store read:\n *  1. argument shape (non-empty session id, an absolute traversal-free `cwd`,\n *     and, when present, single-safe workflow/iteration/project ids);\n *  2. the session is resolved SERVER-side — the live `ctx.sessions.get(id)`\n *     first, then the session controller's persisted `inspect(id)` fallback;\n *  3. the `{HARNESS_DIR}` comes from the SERVER-side session cwd (or the\n *     boot-resolved config root) — never from client-asserted input;\n *  4. the client-asserted `cwd` must EQUAL the resolved session cwd.\n * Only then does `readPanelSnapshot` touch the store, and its own degradation\n * is returned as a value: this endpoint never throws a transport error for a\n * store that refuses.\n *\n * TARGETS ARE NOT THE CLIENT'S JOB: the browser holds `{ sessionId, cwd }` and\n * nothing else, so an omitted `workflowId` / `iterationId` / `projectId` is\n * RESOLVED server-side inside `readPanelSnapshot` (the session's durable pick,\n * then the harness catalog). An asserted id is still shape-validated here and\n * still read against the server-resolved harness root — a client claim can\n * never redirect the read to another workspace.\n *\n * A WORKSPACE WITH NO HARNESS ANSWERS `no-harness`: that is a state of the\n * workspace, not a failed read, so it travels as its own kind instead of an\n * `unavailable` token the panel would have to decode.\n *\n * @module @mstar-harness/dsh/panel/panel-snapshot-endpoint\n */\n\nimport { isAbsolute } from 'node:path'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { TypertContribution } from '@deepseek-ai/dsh-typert-registry'\nimport { TypertRemoteService } from '@deepseek-ai/dsh-typert-protocol'\nimport type { HarnessResolver } from '../gates/_shared.ts'\nimport {\n  MSTAR_DASHBOARD_VIEW_METHOD,\n  MSTAR_MILESTONE_ADD_METHOD,\n  MSTAR_MILESTONE_ASSIGN_METHOD,\n  MSTAR_MILESTONE_REMOVE_METHOD,\n  MSTAR_MILESTONE_UPDATE_METHOD,\n  MSTAR_PANEL_SNAPSHOT_METHOD,\n  MSTAR_PANEL_SNAPSHOT_NAMESPACE,\n} from '../engine-status-wire.ts'\nimport {\n  addMilestone,\n  assignIssueMilestone,\n  readDashboardView,\n  removeMilestone,\n  updateMilestone,\n  type DashboardView,\n  type IssueReceipt,\n  type MilestonePatch,\n  type MilestoneReceipt,\n  type ReadEnvelope,\n} from '@mstar-harness/engine'\nimport { leafSignalStateOf, type LeafSignalState, type PanelSnapshotRead } from './panel-snapshot.ts'\nimport { readPanelSnapshot, resolveWorkflowId, type PanelRetainedReader } from './read-panel-snapshot.ts'\n\n/**\n * One per-view read's answer. The engine's own envelope passes through\n * unmodified (`data` may be `null` for a detail view that resolves to nothing —\n * that is an answer, not a failure), and the two non-answers keep their own\n * kinds so the client never decodes a wire token.\n */\nexport type DashboardViewRead =\n  | { readonly kind: 'ok'; readonly envelope: ReadEnvelope<unknown> }\n  | { readonly kind: 'no-harness' }\n  | { readonly kind: 'unavailable'; readonly reason: string }\n\n/** A query-parameter record: strings only, exactly what the engine's view layer validates. */\nfunction queryParams(value: unknown): Record<string, string | undefined> {\n  if (value === null || typeof value !== 'object' || Array.isArray(value)) return {}\n  const params: Record<string, string | undefined> = {}\n  for (const [key, raw] of Object.entries(value as Record<string, unknown>)) {\n    if (typeof raw === 'string') params[key] = raw\n  }\n  return params\n}\n\n/**\n * ONE answer shape for every milestone write (contract C1): the engine's own\n * refusal passes through verbatim — the client maps nothing and rewords\n * nothing — and a success carries the engine's own receipt.\n */\nexport type MilestoneWriteResult =\n  | { readonly ok: true; readonly receipt: MilestoneReceipt | IssueReceipt }\n  | { readonly ok: false; readonly code: string; readonly message: string }\n\n/** The ONE constructor of a refusal answer (an engine MilestoneError/IssueError). */\nfunction refused(error: unknown): MilestoneWriteResult {\n  const code = (error as { code?: unknown }).code\n  if (typeof code === 'string' && code !== '') {\n    return { ok: false, code, message: (error as Error)?.message ?? code }\n  }\n  return { ok: false, code: 'internal-error', message: (error as Error)?.message ?? 'internal-error' }\n}\n\n/** The contributing package identity (also the invocation id prefix). */\nconst CONTRIBUTING_PACKAGE = '@mstar-harness/dsh'\n/** Logger label for the endpoint's own degradation lines. */\nconst ENDPOINT_LOGGER = 'mstar-panel-snapshot-endpoint'\n/**\n * Logger label of the once-only leaf-signal degradation line. Its own label so\n * an operator reading host logs can grep the capability, not the endpoint.\n */\nconst LEAF_SIGNAL_LOGGER = 'mstar-leaf-signal'\n/**\n * The cordis service key of this half. Deliberately NOT the wire namespace:\n * the `mstar` key already belongs to the engine-status gateway, and a second\n * provider under the same key would collide.\n */\nexport const PANEL_SNAPSHOT_SERVICE = 'mstarPanelSnapshot'\n\n/** Options the endpoint needs from the plugin's apply scope. */\nexport interface PanelSnapshotEndpointOptions {\n  /** The per-workspace `{HARNESS_DIR}` resolver (the same one the gates use). */\n  readonly resolver: Pick<HarnessResolver, 'forWorkspace'>\n  /** The boot-resolved config root when an explicit `harnessDir` is configured. */\n  readonly bootHarnessDir: string | null\n  /**\n   * The apply-scoped catalog reader for the `retained` facts. Optional: a host\n   * without the catalog wiring answers `retained: null` and the snapshot stays\n   * `ok`, so the panel never loses its workspace body to a missing catalog.\n   */\n  readonly readRetained?: PanelRetainedReader\n  /**\n   * Apply-scoped diagnostic sink for the once-only degradation line. Unset in\n   * production, where the gateway writes through `ctx.logger`; a test (or a\n   * host with its own log router) binds it per apply generation.\n   */\n  readonly warnLeafSignal?: (message: string) => void\n}\n\n/** Structural view of the live sessions service (`get(id)` only). */\ninterface SessionsView {\n  get(id: string): unknown\n}\n\n/** Structural view of the session controller's persisted (cold) read. */\ninterface SessionControllerView {\n  inspect(sessionId: string, signal?: AbortSignal): Promise<unknown>\n}\n\n/**\n * The warning-once gate (#619): the FIRST read that finds the shell service\n * absent yields the one line; every later read stays silent while the payload\n * keeps reporting the state. A factory so the flag is per gateway instance.\n * @returns a function yielding the line once, then `undefined`.\n */\nexport function leafSignalWarningOnce(): (state: LeafSignalState) => string | undefined {\n  let warned = false\n  return (state) => {\n    if (warned || state.active) return undefined\n    warned = true\n    return `leaf-seat shell marker inactive: ${state.reason ?? 'shellEnv service absent'} Recovery: ${state.recovery ?? ''}`\n  }\n}\n\n/** The explicit unavailable answer (one constructor — one shape everywhere). */\nfunction unavailable(reason: string): PanelSnapshotRead {\n  return { kind: 'unavailable', reason }\n}\n\n/** A non-empty string, or undefined. */\nfunction nonEmptyString(value: unknown): string | undefined {\n  return typeof value === 'string' && value.trim() !== '' ? value : undefined\n}\n\n/**\n * The `SessionHeader` of either session surface, or undefined.\n *\n * The two surfaces carry it under DIFFERENT keys, read from the host's own types:\n * a live `Session` exposes `header: SessionHeader`\n * (`@deepseek-ai/dsh-session` `Session.header`), while a persisted inspection\n * exposes `meta: SessionHeader` (`@deepseek-ai/dsh-session-persistence`\n * `SessionInspection extends SessionStorageMetadata { meta: SessionHeader }`).\n * Reading only `header` made every cold session answer `session-cwd-absent`\n * while its workspace was right there.\n */\nfunction sessionHeaderOf(value: unknown): { cwd?: unknown } | undefined {\n  const row = value as { header?: unknown; meta?: unknown } | null | undefined\n  const header = row?.header ?? row?.meta\n  return header !== null && typeof header === 'object' ? (header as { cwd?: unknown }) : undefined\n}\n\n/** The session's workspace directory from either surface (`header.cwd` / `meta.cwd`). */\nfunction headerCwdOf(value: unknown): string | undefined {\n  return nonEmptyString(sessionHeaderOf(value)?.cwd)\n}\n\n/**\n * Refuse a client-asserted path that is not a plain absolute path: a relative\n * path would be resolved against the host process cwd (never the caller's), and\n * a `..` segment or NUL byte is a traversal probe, not a workspace.\n */\nfunction isRefusedPath(cwd: string): boolean {\n  if (cwd.includes('\\0')) return true\n  if (!isAbsolute(cwd)) return true\n  return cwd.split(/[\\\\/]+/).includes('..')\n}\n\n/**\n * The ONE cwd acceptance rule, taken by both invocations (`panelSnapshot` and\n * `dashboardView`): the client's claim must be the resolved session's own — never\n * a close match, never another session's workspace.\n *\n * A `boot` resolution is compared like any other: the resolved workspace is the\n * one the host was launched in, and a claim naming anything else is refused.\n * Treating `boot` as a special case let the digest accept a request the per-view\n * read refused, which is how a panel rendered and then failed every destination.\n */\nfunction cwdAccepted(session: { readonly cwd: string; readonly source: 'live' | 'persisted' | 'boot' }, claimed: string): boolean {\n  return claimed === session.cwd\n}\n\n/** An id that could be a catalog id: no separators, no traversal segment. */\nfunction isUnsafeId(value: string): boolean {\n  return value === '.' || value === '..' || /[/\\\\\\u0000]/.test(value)\n}\n\n/**\n * One optional id's argument-shape refusal, or undefined when it is usable.\n * An ABSENT id is legal: the service resolves it from the session's pick and\n * the harness catalog, and only an unresolvable one leaves its member\n * `not-applicable`.\n */\nfunction refusedId(value: unknown, name: string): string | undefined {\n  if (value === undefined || value === null) return undefined\n  const id = nonEmptyString(value)\n  if (id === undefined) return `invalid-${name}-id`\n  return isUnsafeId(id) ? `${name}-id-refused` : undefined\n}\n\n/**\n * The resolved session cwd, or the explicit reason the session is unusable.\n * `source` records WHICH surface answered: `live` (`Session.header.cwd`),\n * `persisted` (`SessionInspection.meta.cwd`) or `boot` (neither declared a\n * workspace, so the plugin reads the workspace the host was launched in and the\n * client's claim is not used as an address).\n */\ntype SessionCwdResolution =\n  | { readonly kind: 'ok'; readonly cwd: string; readonly source: 'live' | 'persisted' | 'boot' }\n  | { readonly kind: 'unavailable'; readonly reason: string }\n\n/**\n * Host-side `mstar/panelSnapshot` service: `/api/mstar/panelSnapshot` serves the\n * composed store-backed snapshot of the session the caller asserts.\n */\nexport class MstarPanelSnapshotGateway extends TypertRemoteService {\n  private readonly resolver: Pick<HarnessResolver, 'forWorkspace'>\n  private readonly bootHarnessDir: string | null\n  private readonly readRetained: PanelRetainedReader | undefined\n  /**\n   * The once-only warning gate. The `shellEnv` probe is NOT cached (a service\n   * that loads later must flip the state), only the \"already warned\" fact is.\n   */\n  private warnLeafSignal: ((message: string) => void) | undefined\n  private nextLeafSignalWarning = leafSignalWarningOnce()\n\n  /**\n   * @param ctx - owning Cordis context.\n   * @param options - the apply-scoped resolver + boot root.\n   */\n  constructor(ctx: Context, options: PanelSnapshotEndpointOptions) {\n    super(ctx, PANEL_SNAPSHOT_SERVICE, { namespace: MSTAR_PANEL_SNAPSHOT_NAMESPACE })\n    this.resolver = options.resolver\n    this.bootHarnessDir = options.bootHarnessDir\n    this.readRetained = options.readRetained\n    this.warnLeafSignal = options.warnLeafSignal\n  }\n\n  /**\n   * Re-arm this gateway's once gate for a NEW apply generation (#619, review).\n   *\n   * The instance is kept across a re-apply (`installPanelSnapshotEndpoint`'s\n   * dedupe), so a gate created in the constructor would stay consumed forever\n   * and a legitimate warning could never be repeated after a reload while the\n   * service is still absent. The registration entry point calls this on every\n   * apply, rebinding the apply-scoped sink too, exactly like the plugin's other\n   * logger sinks.\n   * @param options - the re-applying scope's sink (unset ⇒ `ctx.logger`).\n   */\n  rearmLeafSignalWarning(options: Pick<PanelSnapshotEndpointOptions, 'warnLeafSignal'>): void {\n    this.nextLeafSignalWarning = leafSignalWarningOnce()\n    this.warnLeafSignal = options.warnLeafSignal\n  }\n\n  /**\n   * Serve one session's composed panel snapshot after the validation chain\n   * documented in the module header.\n   * @param sessionId - the session whose snapshot is requested (client-asserted).\n   * @param cwd - the session workspace the client believes it is reading (client-asserted).\n   * @param workflowId - an asserted workflow id; resolved from the session's\n   *   durable pick when omitted (the browser never supplies one).\n   * @param iterationId - an asserted iteration id; resolved from the harness\n   *   catalog when omitted.\n   * @param projectId - an asserted project id; resolved from the harness catalog\n   *   (`_default`, else the single project) when omitted.\n   * @returns the snapshot, the `no-harness` kind, or the explicit unavailable\n   *   state with a reason (`aborted` when the carrier cancelled).\n   */\n  async panelSnapshot(\n    sessionId: string,\n    cwd: string,\n    workflowId?: string,\n    iterationId?: string,\n    projectId?: string,\n  ): Promise<PanelSnapshotRead> {\n    try {\n      return await this.serve(sessionId, cwd, workflowId, iterationId, projectId)\n    } catch (error) {\n      // Never a transport error: an unexpected fault is a degraded answer the\n      // panel already knows how to render.\n      this.ctx.logger(ENDPOINT_LOGGER).warn(\n        `panelSnapshot failed for ${String(sessionId)} (answering unavailable): ${(error as Error)?.message ?? error}`,\n      )\n      return unavailable('internal-error')\n    }\n  }\n\n  /**\n   * Serve ONE engine dashboard view for a session — the per-view read path the\n   * screens use (plan dsh-panel-unification Task 4a). It rides the same typert\n   * contribution and the same server-side validation chain as\n   * {@link panelSnapshot}: the client asserts its session and workspace, never\n   * the ids or the store.\n   *\n   * @param sessionId - the session whose workspace is read (client-asserted).\n   * @param cwd - the workspace the client believes it is reading (client-asserted,\n   *   and required to equal the server-resolved session cwd).\n   * @param view - the engine `DashboardView` name (`workflow-detail`, `iterations`, …).\n   * @param params - the view's own query parameters, strings only.\n   * @param id - the detail record id, for the three detail views.\n   * @returns the engine read envelope, the `no-harness` kind, or an explicit reason.\n   */\n  async dashboardView(\n    sessionId: string,\n    cwd: string,\n    view: string,\n    params?: Record<string, string | undefined>,\n    id?: string,\n  ): Promise<DashboardViewRead> {\n    try {\n      const target = await this.resolveTarget(sessionId, cwd)\n      if (target.kind !== 'ok') return target.kind === 'no-harness' ? { kind: 'no-harness' } : { kind: 'unavailable', reason: target.reason }\n      const name = nonEmptyString(view)\n      if (name === undefined) return { kind: 'unavailable', reason: 'invalid-view' }\n      const envelope = await readDashboardView({\n        context: { harnessDir: target.harnessDir },\n        view: name as DashboardView,\n        params: queryParams(params),\n        ...(nonEmptyString(id) === undefined ? {} : { id: nonEmptyString(id) as string }),\n      })\n      return { kind: 'ok', envelope: envelope as ReadEnvelope<unknown> }\n    } catch (error) {\n      // A view the engine refuses (unknown name, unsafe id, a store fault) is a\n      // degraded READ, never a transport error: the screen renders the reason.\n      this.ctx.logger(ENDPOINT_LOGGER).warn(\n        `dashboardView(${String(view)}) failed for ${String(sessionId)} (answering unavailable): ${(error as Error)?.message ?? error}`,\n      )\n      return { kind: 'unavailable', reason: (error as Error)?.message ?? 'internal-error' }\n    }\n  }\n\n  /**\n   * Create one milestone (engine `addMilestone`) under the observed store\n   * revision (contract C2: `expectedStoreRevision` comes from the roadmap\n   * read's envelope). One request, one transaction, no partial write.\n   */\n  async milestoneAdd(\n    sessionId: string,\n    cwd: string,\n    projectId: string,\n    input: { name: string; target: string | null; ordinal: number },\n    mutation: { operationId: string; expectedStoreRevision: number },\n  ): Promise<MilestoneWriteResult> {\n    try {\n      const target = await this.resolveTarget(sessionId, cwd)\n      if (target.kind !== 'ok') {\n        return {\n          ok: false,\n          code: 'store.not-active',\n          message: \"write refused: \" + (target.kind === 'no-harness' ? 'no harness root resolves for this workspace' : target.reason),\n        }\n      }\n      const receipt = await addMilestone(\n        { harnessDir: target.harnessDir },\n        { projectId, name: input.name, target: input.target ?? null, ordinal: input.ordinal },\n        mutation,\n      )\n      return { ok: true, receipt }\n    } catch (error) {\n      return refused(error)\n    }\n  }\n\n  /** Edit one milestone's name / target / ordinal / status (engine `updateMilestone`). */\n  async milestoneUpdate(\n    sessionId: string,\n    cwd: string,\n    projectId: string,\n    milestoneId: string,\n    patch: MilestonePatch,\n    mutation: { operationId: string; expectedStoreRevision: number },\n  ): Promise<MilestoneWriteResult> {\n    try {\n      const target = await this.resolveTarget(sessionId, cwd)\n      if (target.kind !== 'ok') {\n        return {\n          ok: false,\n          code: 'store.not-active',\n          message: \"write refused: \" + (target.kind === 'no-harness' ? 'no harness root resolves for this workspace' : target.reason),\n        }\n      }\n      const receipt = await updateMilestone({ harnessDir: target.harnessDir }, projectId, milestoneId, patch, mutation)\n      return { ok: true, receipt }\n    } catch (error) {\n      return refused(error)\n    }\n  }\n\n  /**\n   * Assign one issue to a milestone - or unassign it with `milestoneId: null`\n   * (engine `assignIssueMilestone`). The verb authorizes against the ACTIVE\n   * coordinator execution session bound to this DSH session, so the workflow\n   * id of that identity is resolved SERVER-side from the session pick and the\n   * registry, exactly like the reads. A bound session's authorization outcome\n   * (including `issue.scope-refused`) passes through verbatim; a session that\n   * resolves NO active workflow never reaches the verb, and this adapter names\n   * that cause itself under the same code.\n   */\n  async milestoneAssign(\n    sessionId: string,\n    cwd: string,\n    issueId: string,\n    input: { projectId: string; milestoneId: string | null; reason: string },\n    mutation: { operationId: string; actor: string; expectedRevision: number; expectedStoreRevision: number },\n  ): Promise<MilestoneWriteResult> {\n    try {\n      const target = await this.resolveTarget(sessionId, cwd)\n      if (target.kind !== 'ok') {\n        return {\n          ok: false,\n          code: 'store.not-active',\n          message: \"write refused: \" + (target.kind === 'no-harness' ? 'no harness root resolves for this workspace' : target.reason),\n        }\n      }\n      const workflowId = await resolveWorkflowId(target.harnessDir, target.sessionId, target.cwd)\n      if (workflowId === undefined) {\n        // Adapter-worded, not verbatim: the engine never ran because this\n        // session has no active workflow to authorize against. The CODE is the\n        // engine's own family so the client maps one axis; the message names\n        // the real cause instead of an identity mismatch the store never saw.\n        return {\n          ok: false,\n          code: 'issue.scope-refused',\n          message: 'No active workflow resolves for this session, so no coordinator seat authorizes the assignment.',\n        }\n      }\n      const receipt = await assignIssueMilestone(\n        { harnessDir: target.harnessDir, caller: { sessionId: target.sessionId, role: 'coordinator', workflowId } },\n        issueId,\n        input,\n        mutation,\n      )\n      return { ok: true, receipt }\n    } catch (error) {\n      return refused(error)\n    }\n  }\n\n  /**\n   * Remove one EMPTY milestone (engine `removeMilestone`). The emptiness rule\n   * is the engine's: a milestone that still holds issues is refused\n   * (`milestone.not-empty`) and that refusal passes through verbatim — the UI\n   * offers the control regardless and surfaces the store's own words.\n   */\n  async milestoneRemove(\n    sessionId: string,\n    cwd: string,\n    projectId: string,\n    milestoneId: string,\n    mutation: { operationId: string; expectedStoreRevision: number },\n  ): Promise<MilestoneWriteResult> {\n    try {\n      const target = await this.resolveTarget(sessionId, cwd)\n      if (target.kind !== 'ok') {\n        return {\n          ok: false,\n          code: 'store.not-active',\n          message: \"write refused: \" + (target.kind === 'no-harness' ? 'no harness root resolves for this workspace' : target.reason),\n        }\n      }\n      const receipt = await removeMilestone({ harnessDir: target.harnessDir }, projectId, milestoneId, mutation)\n      return { ok: true, receipt }\n    } catch (error) {\n      return refused(error)\n    }\n  }\n\n  /**\n   * The leaf-signal state for ONE read (#619): `ctx.get('shellEnv')` is probed\n   * at call time, never memoized, so a host service injected after `apply` (or\n   * withdrawn) is reflected on the next panel read without a restart. An\n   * apply-time check would be wrong for exactly that reason.\n   *\n   * REACHABILITY (review round 1): this method runs on a PANEL/STATUS READ, so\n   * both the payload state and the once-per-apply-generation log line are\n   * read-triggered. A host that never reads the panel gets neither — that is\n   * stated in the field's reason and the changes fragment instead of being\n   * papered over with a timer: no truthful apply-time signal exists, because a\n   * cordis composition can mount `shellEnv` after this plugin (the deferred\n   * `ctx.inject` exists for exactly that) and no \"will never arrive\" event\n   * exists. No other consumer reads this payload today (`engine-status` does\n   * not), so the panel snapshot is the one disclosure surface.\n   * @returns the disclosure field for this read.\n   */\n  private leafSignal(): LeafSignalState {\n    const state = leafSignalStateOf(this.ctx.get('shellEnv') !== undefined)\n    const line = this.nextLeafSignalWarning(state)\n    if (line === undefined) return state\n    if (this.warnLeafSignal !== undefined) this.warnLeafSignal(line)\n    else this.ctx.logger(LEAF_SIGNAL_LOGGER).warn(line)\n    return state\n  }\n\n  /**\n   * The shared argument chain: shape → server-resolved session → store root →\n   * cwd equality. Both invocations take it, so a second read path cannot drift\n   * from the first one's trust rules.\n   */\n  private async resolveTarget(\n    sessionId: unknown,\n    cwd: unknown,\n  ): Promise<\n    | { readonly kind: 'ok'; readonly harnessDir: string; readonly sessionId: string; readonly cwd: string }\n    | { readonly kind: 'no-harness' }\n    | { readonly kind: 'unavailable'; readonly reason: string }\n  > {\n    const sid = nonEmptyString(sessionId)\n    if (sid === undefined) return { kind: 'unavailable', reason: 'invalid-session-id' }\n    const claimed = nonEmptyString(cwd)\n    if (claimed === undefined) return { kind: 'unavailable', reason: 'invalid-cwd' }\n    if (isRefusedPath(claimed)) return { kind: 'unavailable', reason: 'cwd-refused' }\n    const session = await this.resolveSessionCwd(sid)\n    if (session.kind !== 'ok') return { kind: 'unavailable', reason: session.reason }\n    if (!cwdAccepted(session, claimed)) return { kind: 'unavailable', reason: 'cwd-mismatch' }\n    const harnessDir = this.bootHarnessDir ?? this.resolver.forWorkspace(session.cwd)\n    if (harnessDir === null || harnessDir === '') return { kind: 'no-harness' }\n    return { kind: 'ok', harnessDir, sessionId: sid, cwd: session.cwd }\n  }\n\n  /**\n   * The carrier cancellation of THIS call, when the gateway is serving one.\n   * `ctx.invocation` is set by the typert gateway for the duration of a Remote\n   * call and absent otherwise (an in-process caller), so this reads the real\n   * client timeout / socket close rather than a second timeout of our own.\n   */\n  private carrierSignal(): AbortSignal | undefined {\n    return (this.ctx as { invocation?: { signal?: AbortSignal } }).invocation?.signal\n  }\n\n  /** The validation chain itself (contained by {@link panelSnapshot}). */\n  private async serve(\n    sessionId: unknown,\n    cwd: unknown,\n    workflowId: unknown,\n    iterationId: unknown,\n    projectId: unknown,\n  ): Promise<PanelSnapshotRead> {\n    const signal = this.carrierSignal()\n    // (1) Argument shape — before anything reads the store.\n    const sid = nonEmptyString(sessionId)\n    if (sid === undefined) return unavailable('invalid-session-id')\n    const claimed = nonEmptyString(cwd)\n    if (claimed === undefined) return unavailable('invalid-cwd')\n    if (isRefusedPath(claimed)) return unavailable('cwd-refused')\n    for (const refused of [\n      refusedId(workflowId, 'workflow'),\n      refusedId(iterationId, 'iteration'),\n      refusedId(projectId, 'project'),\n    ]) {\n      if (refused !== undefined) return unavailable(refused)\n    }\n\n    // (2) Resolve the session SERVER-side — the client's claim is not evidence.\n    const session = await this.resolveSessionCwd(sid)\n    if (session.kind !== 'ok') return unavailable(session.reason)\n\n    // (3) The store root comes from the SERVER-side cwd (or the boot root). A\n    // workspace with no harness is NOT an error: `readPanelSnapshot` answers the\n    // `no-harness` kind, which the panel renders as its inactive state.\n    const harnessDir = this.bootHarnessDir ?? this.resolver.forWorkspace(session.cwd)\n\n    // (4) The asserted cwd must be the resolved session's own — the same rule\n    // `dashboardView` takes through `resolveTarget`, so the two paths cannot\n    // disagree about who may read this workspace.\n    if (!cwdAccepted(session, claimed)) return unavailable('cwd-mismatch')\n\n    // An explicit `null` is ABSENT — `refusedId` above already accepted it as\n    // such — so the forward site must agree. `S